 "이 서버는 아직 웹훅을 지원하지 않아요. 서버를 새 버전으로 올려 주세요.": "Dieser Server unterstützt Webhooks noch nicht. Aktualisiere den Server auf eine neue Version.",
 "웹훅은 사람 계정으로 로그인했을 때만 보고 바꿀 수 있어요.": "Webhooks kannst du nur ansehen und ändern, wenn du mit einem Personenkonto angemeldet bist.",
 "작업 공간과 프로젝트가 정해지지 않았어요. 설정 › 고급 › 연결에서 범위를 먼저 정해 주세요.": "Arbeitsbereich und Projekt sind nicht festgelegt. Lege zuerst den Bereich unter Einstellungen › Erweitert › Verbindung fest.",
 "기억 후보가 생기거나 기억이 승인·변경될 때 다른 서비스로 알림을 보내요.": "Sendet eine Benachrichtigung an einen anderen Dienst, wenn ein Erinnerungskandidat entsteht oder eine Erinnerung freigegeben oder geändert wird.",
