 "AI가 고르지 못했어요.": "Die KI konnte sich nicht entscheiden.",
 "이 세션을 찾지 못했어요. 지워졌거나 보관 기간이 지났을 수 있어요.": "Diese Sitzung wurde nicht gefunden. Sie wurde vielleicht gelöscht oder die Aufbewahrungsfrist ist abgelaufen.",
