 "자료 목록을 불러오지 못했어요. 잠시 뒤 다시 불러와요.": "Die Dokumentenliste konnte nicht geladen werden. Es wird gleich erneut versucht.",
 "주제를 불러오지 못해 주제별 보기가 빠졌어요. 지도를 다시 열면 다시 불러와요.": "Die Themen konnten nicht geladen werden, deshalb fehlt die Ansicht nach Thema. Öffne die Karte erneut, um es nochmal zu versuchen.",
 "스크립트 목록을 불러오지 못했어요. 다시 열면 다시 불러와요.": "Die Skriptliste konnte nicht geladen werden. Öffne das Fenster erneut, um es nochmal zu versuchen.",
