 "만들기를 누르면 이 전문가를 넣은 팀이 같이 만들어져요": "Beim Erstellen wird auch ein Team mit diesem Experten angelegt",
 "적용 맥락 확인": "Gesamten Kontext prüfen",
 "로 불러요": "zum Aufrufen",
 "같은 @이름이 이미 있어요. 전문가와 팀은 이름을 함께 써요.": "Diesen @Namen gibt es schon. Experten und Teams teilen sich ihre Namen.",
 "아직 참여자가 없어요. 전문가를 넣어 주세요.": "Noch keine Mitglieder. Füge Experten hinzu.",
 "넣을 전문가 고르기": "Experten zum Hinzufügen auswählen",
 "전문가 추가": "Experten hinzufügen",
 "넣을 수 있는 전문가를 모두 넣었어요.": "Alle verfügbaren Experten sind schon dabei.",
 "먼저 전문가를 만들어 주세요.": "Erstelle bitte zuerst einen Experten.",
 "전문가에게 바로 물어봐요": "Direkt einen Experten fragen",
 "전문가 여럿이 정한 순서대로 말하며 하나의 결과를 만들어요. 연결된 채널에 글을 쓰면 회의가 시작돼요.": "Mehrere Experten sprechen in festgelegter Reihenfolge und erarbeiten ein gemeinsames Ergebnis. Ein Beitrag in einem verbundenen Kanal startet die Besprechung.",
 "아직 팀이 없어요. 새 팀을 만들어 전문가 여럿이 함께 회의하게 해 보세요.": "Noch keine Teams. Erstelle ein neues Team, damit mehrere Experten gemeinsam beraten können.",
 "팀은 전문가로 만들어요. 먼저 전문가를 만들어 주세요.": "Teams bestehen aus Experten. Erstelle bitte zuerst einen Experten.",
