 "전문가를 만들었어요.": "Experte erstellt.",
 "새 전문가": "Neuer Experte",
 "역할·지시·모델·쓸 수 있는 스킬을 한 번 정해 두면, Claude Code·Codex 어디서든 @이름으로 불러 일을 맡겨요.": "Lege Rolle, Anweisungen, Modell und nutzbare Skills einmal fest, dann kannst du ihm in Claude Code oder Codex per @Name Aufgaben übergeben.",
