 "모두 움직임": "Alles läuft",
 "고친 문장을 검토 대기에 넣어요. 검토 후 새 기억으로 승인할 수 있어요.": "Der korrigierte Text kommt in die Prüfung. Danach kannst du ihn als neue Erinnerung freigeben.",
 "검토 대기에 추가해요. 승인한 뒤 모든 에이전트가 자료로 써요.": "Wird zur Prüfung hinzugefügt. Nach deiner Freigabe nutzen alle Agenten es als Grundlage.",
 "이미 수집한 내용이에요. 기억 목록에서 상태를 확인하세요.": "Das wurde bereits erfasst. Den Status findest du in der Erinnerungsliste.",
 "검토 대기에 들어갔어요. 기억 › 검토 대기에서 승인하면 저장돼요.": "Wurde zur Prüfung hinzugefügt. Wenn du unter Memory › Ausstehende Prüfung freigibst, wird es gespeichert.",
 "기억 검토 규칙 보기": "So funktioniert die Prüfung von Erinnerungen",
