 "연결했어요. 에이전트를 다시 시작하면 적용돼요.": "Verbunden. Starte den Agenten neu, damit es wirkt.",
 "연결을 끊고 원래 설정으로 돌려놨어요.": "Verbindung getrennt und die ursprünglichen Einstellungen wiederhergestellt.",
 "Codex 설정에 이미 arkism 공급자가 있어요. 직접 지운 뒤 다시 해 주세요.": "In den Codex-Einstellungen gibt es schon einen arkism-Anbieter. Entferne ihn selbst und versuche es dann noch einmal.",
 "에이전트 설정 파일을 읽지 못했어요.": "Die Einstellungsdatei des Agenten konnte nicht gelesen werden.",
 "연결하지 못했어요.": "Verbindung fehlgeschlagen.",
 "이미 연결하는 중이에요.": "Es wird bereits verbunden.",
 "이 PC에서 찾지 못했어요.": "Auf diesem PC nicht gefunden.",
 "연결한 에이전트는 이 PC의 Arkism 중계기로 요청을 보내고, 설정 › 에이전트에서 켠 모델 중에서 자동으로 골라 답해요. 각자 로그인은 그대로 써요.": "Verbundene Agenten schicken ihre Anfragen an das Arkism-Gateway auf diesem PC. Es wählt automatisch eines der Modelle, die du unter Einstellungen › Agenten eingeschaltet hast. Jeder Agent behält sein eigenes Login.",
 "기본 모델이 ‘자동’이 돼요. /model에서 다른 모델도 고를 수 있어요.": "Das Standardmodell wird zu ‚Auto‘. Mit /model kannst du trotzdem andere Modelle wählen.",
 "~/.codex/config.toml에 Arkism 공급자를 넣고 모델을 ‘자동’으로 바꿔요.": "Trägt einen Arkism-Anbieter in ~/.codex/config.toml ein und stellt das Modell auf ‚Auto‘.",
 "API 키로 로그인한 Gemini CLI만 돼요. Google 로그인은 주소 설정을 무시해요.": "Funktioniert nur mit Gemini CLI, das mit einem API-Schlüssel angemeldet ist. Bei einem Google-Login wird die Adresse ignoriert.",
 "판별 모델": "Prüfmodell",
 "내 모델": "Eigenes Modell",
 "판별 모델 주소": "Adresse des Prüfmodells",
