 "고치는 중…": "Wird behoben…",
 "점검하는 중…": "Wird geprüft…",
 "점검하지 못했어요.": "Die Prüfung ist fehlgeschlagen.",
 "점검": "Prüfen",
 "예: 회사 고객 이름은 기억하지 마. 배포·테스트 규칙은 꼭 기억해.": "z. B. Merk dir keine Kundennamen. Merk dir unbedingt die Regeln für Deployment und Tests.",
