 "무엇을 기억할지 메모": "Was soll gemerkt werden?",
 "Arkism이 기억을 고를 때 참고해요. 비밀값·개인정보 규칙보다 앞서지는 않아요.": "Arkism nutzt das bei der Auswahl von Erinnerungen. Die Regeln zu Geheimnissen und persönlichen Daten haben trotzdem Vorrang.",
 "에이전트 기억 가져오기": "Agent-Erinnerungen importieren",
