 "가져오지 못했어요. 잠시 뒤 다시 시도해 주세요.": "Der Import ist fehlgeschlagen. Versuch es gleich noch einmal.",
 "로그인할 때 Arkism 시작": "Arkism bei der Anmeldung starten",
 "로그인할 때 Arkism이 트레이에서 시작해요.": "Arkism startet bei der Anmeldung im Tray.",
