 "AI가 최근 기억과 후보를 보고 새 스킬을 찾는 중이에요…": "Die KI sucht in letzten Erinnerungen und Kandidaten nach neuen Skills…",
 "(없음)": "(keine)",
 "지금은 새 스킬로 만들 만한 반복 요청이 없어요.": "Im Moment gibt es keine wiederkehrenden Anfragen, die einen neuen Skill lohnen.",
