 "합친 SKILL.md · 원본 저장소에 붙여 넣어 주세요": "Zusammengeführte SKILL.md · bitte in das Originalrepository einfügen",
 "다른 스킬이에요": "Das sind verschiedene Skills",
 "두 기억이 같은 말을 해요. 하나만 있어도 에이전트가 똑같이 알아요.": "Beide Erinnerungen sagen dasselbe. Mit nur einer wissen Agenten genauso viel.",
 "남길 기억이 더 자세해요. 다른 하나의 내용이 거기에 들어 있다고 봤어요.": "Die Erinnerung, die bleibt, ist detaillierter. Der Inhalt der anderen scheint darin enthalten zu sein.",
 "새 기억이 예전 기억과 반대예요. 지금 생각은 새 기억이라고 봤어요.": "Die neue Erinnerung widerspricht der alten. Die neue gilt als deine aktuelle Sichtweise.",
 "서로 다른 말을 하는 기억, 새 것으로 바꿀까요?": "Diese Erinnerungen widersprechen sich. Durch die neue ersetzen?",
 "비슷한 기억 2개, 하나로 합칠까요?": "2 ähnliche Erinnerungen. Zu einer zusammenführen?",
