 "서로 다른 말을 하고 있어요": "Sie sagen Unterschiedliches",
 "두 기억이 같은 뜻이에요. 하나만 남겨 두면 AI가 덜 헷갈려요.": "Beide Erinnerungen bedeuten dasselbe. Mit nur einer ist die KI weniger verwirrt.",
 "두 기억을 함께 따를 수 없어요. 지금 생각에 맞는 쪽만 남겨요.": "Beide Erinnerungen lassen sich nicht zugleich befolgen. Behalte nur die, die zu deiner aktuellen Sichtweise passt.",
