 "시작 노드에는 선을 이을 수 없어요.": "Mit dem Start-Node kann keine Linie verbunden werden.",
 "되돌아가는 선이에요. 최대 2번까지 다시 돌아요. 선을 눌러 횟수와 갈래 이름을 바꿀 수 있어요.": "Das ist eine Rücksprung-Linie. Sie wiederholt sich bis zu 2-mal. Klick auf die Linie, um Anzahl und Zweigname zu ändern.",
 "노드마다": "Pro Node",
