 "노드 설정": "Node-Einstellungen",
 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "Klick auf einen Node, um ihn hier zu bearbeiten. Zieh den Ausgangspunkt zum nächsten Node, um sie zu verbinden. Verbindest du mit einem früheren Node, entsteht eine Rücksprung-Linie. Klick auf eine Linie, um ihre Einstellungen zu öffnen. Mit dem Mausrad zoomst du, mit Mittelklick-Ziehen oder gedrückter Leertaste und Ziehen verschiebst du die Ansicht.",
 "노드": "Node",
 "되돌아가는 선": "Rücksprung-Linie",
 "고르세요": "Bitte wählen",
 "출력이 {\"ok\": true/false, …}면 통과·실패 갈래로 나뉘어요. 처음 한 번은 빌드에 1~2초, 30초 안에 끝나야 해요. 토큰은 들지 않아요.": "Lautet die Ausgabe {\"ok\": true/false, …}, teilt sie sich in die Zweige Bestanden und Fehlgeschlagen. Beim ersten Mal dauert der Build 1–2 Sekunden und muss innerhalb von 30 Sekunden fertig sein. Verbraucht keine Tokens.",
 "배포·게시처럼 되돌릴 수 없는 단계 바로 앞에 두세요. 답이 올 때까지 멈춰요.": "Setz ihn direkt vor Schritte, die sich nicht rückgängig machen lassen, etwa Deployen oder Veröffentlichen. Er pausiert, bis eine Antwort kommt.",
