 "선": "Linie",
 "통과, 근거 부족…": "Bestanden, zu wenig Belege…",
 "갈래 이름": "Name des Zweigs",
 "이름 붙은 갈래가 둘 이상이면 AI가 결과를 보고 하나를 골라요": "Bei zwei oder mehr benannten Zweigen liest die KI das Ergebnis und wählt einen aus",
 "갈래": "Zweig",
 "최대 몇 번 되돌아갈까요": "Wie oft maximal zurückspringen?",
 "넘으면 실행을 멈추고 이유를 남겨요. 성공한 노드 결과는 그대로 두고 대상부터 다시 돌아요.": "Wird der Wert überschritten, stoppt die Ausführung und der Grund wird festgehalten. Ergebnisse erfolgreicher Knoten bleiben erhalten, und es geht ab dem Ziel erneut los.",
 "앞으로 가는 선이에요. 앞 노드로 이으면 되돌아가는 선이 돼요.": "Das ist eine Linie nach vorn. Verbindest du sie mit einem früheren Knoten, wird daraus eine Rücksprung-Linie.",
 "선 지우기": "Linie löschen",
 "이 노드만 실행": "Nur diesen Knoten ausführen",
 "넣을 값 (비워도 돼요)": "Eingabewert (optional)",
 "저장한 뒤에 실행할 수 있어요": "Speichere zuerst, dann kannst du ausführen",
 "앞 단계는 건너뛰고 이 노드에만 값을 넣어 돌려요. 결과는 최근 실행에 남아요.": "Überspringt die vorherigen Schritte und führt nur diesen Knoten mit dem Eingabewert aus. Das Ergebnis bleibt in den letzten Ausführungen erhalten.",
 "단계 추가 — 그래프로 바뀌어요": "Schritt hinzufügen — wechselt zum Graph",
 "구조 검토 닫기": "Strukturprüfung schließen",
 "AI 제안": "KI-Vorschläge",
 "제안": "Vorschläge",
 "무시": "Ignorieren",
 "그 노드나 선이 바뀌어 다시 받아야 해요": "Dieser Knoten oder diese Linie hat sich geändert, du musst die Vorschläge neu abrufen",
 "[적용]을 누르면 그래프가 바로 바뀌고, 나머지 제안은 그대로 남아요. 실행 기록이 쌓이면 자주 다시 도는 노드도 짚어요.": "Mit [Anwenden] ändert sich der Graph sofort, die übrigen Vorschläge bleiben erhalten. Sobald es Ausführungsverläufe gibt, werden auch Knoten markiert, die oft wiederholt laufen.",
