 "검증됨": "Geprüft",
 "만료됨": "Abgelaufen",
 "근거를 읽을 수 없어요. 권한·삭제·기록 변경 여부를 확인하고 접었다 다시 펼쳐 주세요.": "Die Belege können nicht gelesen werden. Prüfe, ob sich Berechtigungen, Löschungen oder der Verlauf geändert haben, und klappe es dann ein und wieder aus.",
 "저장된 본문이 없어요.": "Kein gespeicherter Text vorhanden.",
 "미기록": "Nicht erfasst",
 "기록된 원문 구간": "Erfasster Ausschnitt der Quelle",
 "당시 본문 위치가 없어 현재 출처를 표시해요.": "Die damalige Textposition wurde nicht erfasst, deshalb wird die aktuelle Quelle angezeigt.",
 "근거를 검토한 뒤 확인 조건을 검사하세요. 확인해도 자동 실행되지는 않아요.": "Sieh dir die Belege an und prüfe dann die Bestätigungsbedingungen. Auch nach der Bestätigung wird nichts automatisch ausgeführt.",
 "서로 다른 실행 3건 이상이 필요해요.": "Es sind mindestens 3 verschiedene Ausführungen nötig.",
 "관측 횟수 기반 점수가 기준보다 낮아요.": "Der auf der Anzahl der Beobachtungen basierende Wert liegt unter dem Schwellenwert.",
 "현재 상태에서는 확인할 수 없어요. 목록을 다시 조회해 주세요.": "Im aktuellen Zustand kann nicht bestätigt werden. Bitte lade die Liste neu.",
 "확인 조건 검사": "Bedingungen prüfen",
 "관계 확인": "Beziehung bestätigen",
 "관계를 확인했어요.": "Beziehung bestätigt.",
 "확인 조건을 충족했어요. 이 관계를 확인하려면 ‘관계 확인’을 눌러 주세요.": "Die Bedingungen sind erfüllt. Klicke auf ‚Beziehung bestätigen‘, um diese Beziehung zu bestätigen.",
 "확인되지 않았어요. 목록을 다시 조회해 주세요.": "Nicht bestätigt. Bitte lade die Liste neu.",
 "처리 결과를 확인하지 못했어요. 권한이나 근거가 바뀌었을 수 있으니 목록을 다시 조회해 주세요.": "Das Ergebnis konnte nicht überprüft werden. Berechtigungen oder Belege haben sich möglicherweise geändert, bitte lade die Liste neu.",
 "내용을 확인한 뒤 기존 화면에서 검토하거나 고칠 수 있어요.": "Nachdem du den Inhalt geprüft hast, kannst du ihn auf dem bisherigen Bildschirm ansehen oder korrigieren.",
 "여러 관측을 묶은 교훈이에요. 대표 후보 하나만 검토하며, 묶음 전체를 승인하지 않아요.": "Eine Erkenntnis, die mehrere Beobachtungen bündelt. Nur ein repräsentativer Kandidat wird geprüft, die ganze Gruppe wird nicht freigegeben.",
 "기억 확인·정정": "Erinnerung prüfen und korrigieren",
 "후보 검토": "Kandidat prüfen",
 "대표 후보 검토": "Repräsentativen Kandidaten prüfen",
 "기록을 열 수 없어요. 권한이나 내용이 바뀌었을 수 있으니 목록을 다시 조회해 주세요.": "Der Eintrag kann nicht geöffnet werden. Berechtigungen oder Inhalt haben sich möglicherweise geändert, bitte lade die Liste neu.",
 "같은 작업에서 이어서 사용한 스킬의 관측이에요. 인과관계나 실행 허가를 뜻하지 않아요.": "Eine Beobachtung zu Skills, die in derselben Aufgabe nacheinander verwendet wurden. Sie bedeutet weder Ursache und Wirkung noch eine Erlaubnis zur Ausführung.",
 "사용자에 대한 관측과 추정이에요. 현재 지시나 실행 승인을 뜻하지 않아요.": "Beobachtungen und Vermutungen über den Nutzer. Sie sind keine aktuellen Anweisungen und keine Freigabe zur Ausführung.",
 "작업에서 얻은 해석이에요. 사실이나 실행 승인을 뜻하지 않아요.": "Eine Deutung, die aus der Arbeit gewonnen wurde. Sie ist weder eine Tatsache noch eine Freigabe zur Ausführung.",
