 "검사 기록 없음": "Noch keine Prüfungen",
 "알림만이면 PR에 코멘트만 남겨요. 막으면 blocking 지적이 있는 PR은 검사가 실패해 병합할 수 없어요.": "Bei „Nur benachrichtigen“ bleiben nur Kommentare im PR. Bei „Blockieren“ schlägt die Prüfung für PRs mit blockierenden Hinweisen fehl, sodass sie nicht gemergt werden können.",
