 "판정 모델이 요청 내용과 모델마다 적은 설명을 보고 알맞은 모델로 보내요.": "Das Bewertungsmodell liest jede Anfrage und die Beschreibung, die du für jedes Modell geschrieben hast, und leitet sie an das passende Modell weiter.",
 "모델 계열별 분배가 멈췄어요. 켜면 바로 다시 나눠요.": "Die Verteilung nach Modellfamilie ist pausiert. Wenn du sie einschaltest, wird sofort wieder verteilt.",
