 "세션 ID": "Sitzungs-ID",
 "이 서버는 아직 대화 보기를 지원하지 않아요.": "Dieser Server unterstützt die Konversationsansicht noch nicht.",
 "이 세션은 보관된 대화가 없어요. 대화 원문은 수집된 뒤 7일 동안만 보관돼요.": "Für diese Sitzung gibt es keine gespeicherte Konversation. Originaltexte werden nur 7 Tage nach der Erfassung aufbewahrt.",
 "보관된 대화가 만료됐거나 지워졌어요.": "Die gespeicherte Konversation ist abgelaufen oder wurde gelöscht.",
 "이 형식의 대화는 아직 볼 수 없어요.": "Konversationen in diesem Format können noch nicht angezeigt werden.",
 "길어서 앞부분만 보여요.": "Zu lang, es wird nur der Anfang angezeigt.",
 "보여 줄 대화가 없어요.": "Keine Konversation zum Anzeigen.",
 "대화": "Konversation",
 "지울 권한이 없어요.": "Du hast keine Berechtigung zum Löschen.",
