 "정보": "Info",
 "고정 과제로 비교 실행": "Vergleich mit festen Aufgaben starten",
 "관리 계정의 데스크톱 앱에서 비교를 실행할 수 있어요.": "Vergleiche kannst du in der Desktop-App mit einem Admin-Konto starten.",
 "고정 비교 계획이 있는 검토 대기 버전에서 실행할 수 있어요.": "Das geht bei Versionen, die auf Prüfung warten und einen festen Vergleichsplan haben.",
 "서버를 다시 조회해 주세요.": "Bitte frag den Server erneut ab.",
 "SSH 서버 이름을 확인해 주세요.": "Bitte prüfe den SSH-Servernamen.",
 "설정과 실행 기록을 확인하는 중…": "Einstellungen und Ausführungsverlauf werden geprüft…",
 "이 버전의 고정 과제·실행 조건과 일치하는 평가 설정이 없어요.": "Es gibt keine Bewertungseinstellungen, die zu den festen Aufgaben und Ausführungsbedingungen dieser Version passen.",
 "평가 설정": "Bewertungseinstellungen",
 "비교 실행": "Vergleich starten",
 "동일 과제로 기존 버전과 후보를 비교해요. 실행만으로 승인·적용되지는 않아요.": "Vergleicht die bisherige Version mit dem Kandidaten anhand derselben Aufgaben. Das Ausführen allein genehmigt oder übernimmt nichts.",
 "불러오지 못했어요. SSH 연결과 평가 서버의 범위·API 설정을 확인해 주세요.": "Laden fehlgeschlagen. Prüfe die SSH-Verbindung sowie Bereich und API-Einstellungen des Bewertungsservers.",
 "비교 실행 중이에요.": "Vergleich läuft.",
 "비교 결과를 저장했어요. 승인·적용은 별도로 진행해 주세요.": "Vergleichsergebnis gespeichert. Genehmigen und Übernehmen musst du separat machen.",
 "저장된 결과 없이 실행이 끝났거나 중단됐어요. 재실행 전에 서버에서 실행 상태를 확인해 주세요.": "Die Ausführung wurde ohne gespeicherte Ergebnisse beendet oder abgebrochen. Prüfe den Ausführungsstatus auf dem Server, bevor du sie erneut startest.",
 "미달": "Nicht bestanden",
 "평가 다시 읽기": "Bewertung neu laden",
 "상태 확인": "Status prüfen",
 "실행 상태를 확인하는 중…": "Ausführungsstatus wird geprüft…",
 "결과를 확인하지 못했어요. 같은 버튼으로 다시 확인하세요. 같은 실행 요청은 중복 실행하지 않아요.": "Das Ergebnis konnte nicht bestätigt werden. Prüfe es mit derselben Schaltfläche erneut. Dieselbe Ausführungsanfrage wird nicht doppelt ausgeführt.",
 "교훈으로 개선안 만들기": "Verbesserung aus Erkenntnissen erstellen",
 "개선안을 생성하는 중…": "Verbesserung wird erstellt…",
 "생성 결과를 확인하지 못했어요. 같은 요청으로 다시 확인하세요. 완료된 요청은 새로 생성하지 않아요.": "Das Ergebnis konnte nicht bestätigt werden. Prüfe es mit derselben Anfrage erneut. Abgeschlossene Anfragen werden nicht neu erstellt.",
 "입력 다시 선택": "Eingabe neu auswählen",
 "보류 요청을 지우지 못했어요. 앱 저장 공간을 확인해 주세요.": "Die ausstehende Anfrage konnte nicht gelöscht werden. Prüfe den Speicher der App.",
 "처리 결과를 확인할 생성 요청이 있어요.": "Es gibt eine Erstellungsanfrage, deren Ergebnis noch geprüft werden muss.",
 "생성 결과 다시 확인": "Erstellungsergebnis erneut prüfen",
 "개선안 생성은 관리 계정에서 시작할 수 있어요.": "Verbesserungen kannst du nur mit einem Admin-Konto erstellen.",
 "보류 요청을 읽지 못했어요. 중복 생성을 막기 위해 새 요청을 시작하지 않아요. 앱 저장 공간을 확인해 주세요.": "Die ausstehende Anfrage konnte nicht gelesen werden. Um doppeltes Erstellen zu vermeiden, wird keine neue Anfrage gestartet. Prüfe den Speicher der App.",
 "현재 기준 버전을 확인하는 중…": "Aktuelle Basisversion wird geprüft…",
 "개선안 생성": "Verbesserung erstellen",
 "현재 기준 버전을 읽지 못했어요. 접었다 다시 펼쳐 주세요.": "Die aktuelle Basisversion konnte nicht gelesen werden. Klapp den Bereich ein und wieder aus.",
 "개선안과 버전 검토": "Verbesserungen und Versionsprüfung",
