 "중단됨": "Abgebrochen",
 "저장된 내용이 없어요.": "Nichts gespeichert.",
 "버전과 평가를 불러오는 중…": "Versionen und Bewertungen werden geladen…",
 "검토할 버전": "Zu prüfende Versionen",
 "· 사용 중": "· in Verwendung",
 "스킬 원문과 평가는 검토 자료예요. 조회만으로 승인되거나 실행되지 않아요.": "Skill-Quelltext und Bewertungen dienen nur zur Prüfung. Ansehen genehmigt oder startet nichts.",
 "평가를 읽는 중…": "Bewertung wird gelesen…",
 "버전 원문": "Versionsquelle",
 "기존 버전 원문": "Bisherige Versionsquelle",
 "이 버전에 연결된 평가가 없어요.": "Mit dieser Version sind keine Bewertungen verknüpft.",
 "모델 자기평가": "Selbstbewertung des Modells",
 "평가 기록": "Bewertungsverlauf",
 "판정 없음": "Kein Urteil",
 "후보 제외": "Kandidat ausschließen",
 "이 버전으로 복귀": "Zu dieser Version zurückkehren",
 "이 버전 적용": "Diese Version anwenden",
 "반영 결과를 확인하지 못했어요. 권한·평가 기준·기록 변경 여부를 확인하려면 다시 조회하세요.": "Das Ergebnis konnte nicht bestätigt werden. Frag erneut ab, um Berechtigungen, Bewertungskriterien und Änderungen am Verlauf zu prüfen.",
 "버전이나 평가를 읽지 못했어요. 권한·삭제·기록 변경 여부를 확인하고 다시 조회하세요.": "Versionen oder Bewertungen konnten nicht gelesen werden. Prüfe Berechtigungen, Löschungen und Änderungen am Verlauf und frag dann erneut ab.",
 "버전 목록을 읽지 못했어요. 접었다 다시 펼쳐 주세요.": "Die Versionsliste konnte nicht gelesen werden. Klapp sie zu und wieder auf.",
 "시험 가능": "Test möglich",
 "종료됨": "Beendet",
 "기간 종료": "Zeitraum abgelaufen",
 "근거 또는 기준판 변경": "Beleg oder Basisversion geändert",
 "제한적으로 시험 적용": "Begrenzt testen",
 "시험 기록을 읽는 중…": "Testprotokoll wird gelesen…",
 "시험 기록": "Testprotokoll",
 "이 페이지에 표시할 시험 기록이 없어요.": "Auf dieser Seite gibt es keine Testeinträge.",
 "첫 기록으로": "Zum ersten Eintrag",
 "시험 기록을 읽지 못했어요.": "Das Testprotokoll konnte nicht gelesen werden.",
 "기록 다시 조회": "Protokoll neu laden",
 "현재 불러올 수 있는 버전이 없어요.": "Aktuell sind keine Versionen zum Laden verfügbar.",
 "에이전트에 보낼 시험 요청": "Testanfrage an den Agenten",
 "종료 시각이 지났어요. 상태를 다시 확인해 주세요.": "Die Endzeit ist vorbei. Prüf den Status bitte noch einmal.",
 "복사했어요. 선택한 프로그램에 보내 주세요.": "Kopiert. Sende es an das ausgewählte Programm.",
 "요청 내용을 선택했어요. 직접 복사해 주세요.": "Der Anfragetext ist markiert. Kopiere ihn bitte selbst.",
 "시험 종료": "Test beenden",
 "시험을 종료하고 현재 반환 버전을 확인했어요. 이미 실행 중인 작업은 강제로 중단하지 않아요.": "Der Test wurde beendet und die aktuell ausgelieferte Version bestätigt. Bereits laufende Aufgaben werden nicht zwangsweise gestoppt.",
 "종료 결과를 확인하지 못했어요. 상태를 새로고침해 주세요.": "Das Ergebnis des Beendens konnte nicht bestätigt werden. Aktualisiere den Status.",
 "현재 상태를 읽지 못했어요. 기록을 다시 선택해 주세요.": "Der aktuelle Status konnte nicht gelesen werden. Wähl den Eintrag bitte erneut aus.",
 "시험을 준비하는 중…": "Test wird vorbereitet…",
 "준비 결과를 확인하지 못했어요. 같은 요청으로 다시 확인하세요.": "Das Ergebnis der Vorbereitung konnte nicht bestätigt werden. Prüf es noch einmal mit derselben Anfrage.",
 "같은 시험 요청 다시 확인": "Dieselbe Testanfrage erneut prüfen",
 "시험 입력 다시 선택": "Testeingabe neu auswählen",
 "앱 저장 공간을 확인해 주세요.": "Prüf bitte den App-Speicher.",
 "확인할 시험 준비 요청이 남아 있어요.": "Eine Testvorbereitung wartet noch auf Prüfung.",
 "고정 비교를 거쳐 승인된 후보에서 새 시험을 준비할 수 있어요.": "Neue Tests lassen sich aus Kandidaten vorbereiten, die den festen Vergleich bestanden haben und freigegeben wurden.",
 "종료 시각": "Endzeit",
 "미래의 종료 시각을 선택해 주세요.": "Wähl bitte eine Endzeit in der Zukunft.",
 "요청을 보관하지 못했어요. 앱 저장 공간을 확인해 주세요.": "Die Anfrage konnte nicht gespeichert werden. Prüf bitte den App-Speicher.",
 "현재 후보나 보류 요청을 읽지 못해 새 시험을 준비할 수 없어요. 기존 기록은 확인할 수 있어요.": "Ein neuer Test kann nicht vorbereitet werden, weil der aktuelle Kandidat oder die ausstehende Anfrage nicht gelesen werden konnte. Vorhandene Einträge kannst du weiterhin ansehen.",
 "개요": "Übersicht",
 "아직 기록이 없어요.": "Noch keine Einträge.",
 "공시 단가로 계산": "Nach Listenpreisen berechnet",
 "이 기간에 기록된 세션이 없어요.": "In diesem Zeitraum wurden keine Sitzungen aufgezeichnet.",
 "모델별": "Nach Modell",
 "시각": "Zeit",
 "걸린 시간": "Dauer",
 "이 기간에 Arkism 라우터를 거친 요청이 없어요. 워크플로우·하위 작업이 라우터로 모델을 고르면 여기에 쌓여요.": "In diesem Zeitraum lief keine Anfrage über den Arkism Router. Wenn Workflows oder Teilaufgaben über den Router ein Modell wählen, erscheinen sie hier.",
