 "예: 메일 앱": "z. B. Mail-App",
 "강조 버튼은 화면에 하나만 둬요.": "Pro Bildschirm gibt es nur eine hervorgehobene Schaltfläche.",
 "정한 폴더 안의 파일을 읽고 써요. 마지막 경로를 열어 줄 폴더로 바꿔 주세요.": "Liest und schreibt Dateien in den Ordnern, die du festlegst. Ersetze den letzten Pfad durch den Ordner, den du freigeben willst.",
 "웹 페이지를 가져와 마크다운으로 읽어요.": "Ruft Webseiten ab und liest sie als Markdown.",
 "지식 그래프 형태의 간단한 기억 저장소예요.": "Ein einfacher Gedächtnisspeicher in Form eines Wissensgraphen.",
 "Playwright로 브라우저를 열고 페이지를 조작해요.": "Öffnet mit Playwright einen Browser und bedient Seiten.",
 "GitHub 공식 원격 서버예요. 추가한 뒤 에이전트에서 로그인해요.": "Der offizielle Remote-Server von GitHub. Melde dich nach dem Hinzufügen im Agenten an.",
 "라이브러리의 최신 문서와 예제를 찾아 줘요.": "Findet aktuelle Dokumentation und Beispiele zu Bibliotheken.",
 "공유 폴더": "Gemeinsamer Ordner",
 "GitHub에서 스킬 설치": "Skill von GitHub installieren",
 "owner/repo 또는 owner/repo/경로, GitHub 주소를 넣어요. 받은 파일은 실행하지 않아요.": "Gib owner/repo, owner/repo/Pfad oder eine GitHub-Adresse ein. Heruntergeladene Dateien werden nie ausgeführt.",
 "미리보기": "Vorschau",
 "설치": "Installieren",
 "GitHub 주소를 owner/repo 또는 owner/repo/경로 형태로 넣어 주세요.": "Gib die GitHub-Quelle als owner/repo oder owner/repo/Pfad ein.",
 "서버가 저장소를 내려받아 확인하고 있어요. 1분쯤 걸려요…": "Der Server lädt das Repository herunter und prüft es. Das dauert etwa eine Minute…",
 "아직 답이 없어요. 에이전트 동기화가 켜져 있는지 확인해 주세요.": "Noch keine Antwort. Prüf bitte, ob die Agent-Synchronisierung eingeschaltet ist.",
 "이 경로에서 SKILL.md를 찾지 못했어요.": "Unter diesem Pfad wurde keine SKILL.md gefunden.",
 "설명 없음": "Keine Beschreibung",
 "이미 있는 스킬은 이 버전으로 바꾸기 (업데이트)": "Bereits vorhandene Skills durch diese Version ersetzen (Update)",
 "넣을 에이전트를 골라 주세요.": "Wähl bitte die Agenten aus, in die installiert werden soll.",
 "설치를 요청했어요. 서버가 1분 안에 설치해요…": "Installation angefragt. Der Server installiert innerhalb einer Minute…",
 "설치 결과를 아직 받지 못했어요. 잠시 뒤 스킬 목록을 확인해 주세요.": "Noch kein Installationsergebnis. Sieh in einem Moment in die Skill-Liste.",
 "프로그램": "Programm",
 "자주 쓰는 서버": "Beliebte Server",
 "상태 아이콘 색: 초록 정상 · 주황 확인 필요 · 빨강 연결 문제·멈춤": "Statusfarben: grün in Ordnung · orange bitte prüfen · rot Verbindungsproblem oder angehalten",
 "개선안 만들기 → 기존 버전과 비교 → 검토·승인 → 실제 작업에 시험 적용 순서로 진행해요.": "Ablauf: Verbesserung erstellen → mit der bisherigen Version vergleichen → prüfen und freigeben → an echter Arbeit testen.",
 "저장소 주소를 넣으면 안에 있는 스킬을 보여 줘요. 받은 파일은 실행하지 않아요.": "Gib eine Repository-Adresse ein, um die enthaltenen Skills zu sehen. Heruntergeladene Dateien werden nie ausgeführt.",
 "에이전트가 일할 때 꺼내 쓰는 작업 방법이에요.": "Arbeitsweisen, die Agenten bei der Arbeit abrufen.",
 "앱·메일·웹·문서에 쓰는 색·글꼴·규칙 모음이에요. 하나를 고르면 오른쪽에서 자세히 볼 수 있어요.": "Sammlungen von Farben, Schriftarten und Regeln für Apps, E-Mails, Web und Dokumente. Wähl eine aus, dann siehst du rechts die Details.",
 "슬라이드 프롬프트": "Folien-Prompts",
 "변수 값을 채우고 바로 만들거나, ComfyUI 워크플로우로 보내요.": "Fülle die Variablen aus und erstelle es sofort, oder sende es an einen ComfyUI-Workflow.",
 "발표·보고용 슬라이드 프롬프트와 만드는 스크립트를 모아 둬요. 카드를 고르면 오른쪽에서 고치고 바로 만들 수 있어요.": "Hier sammelst du Folien-Prompts für Vorträge und Berichte samt Skripten zum Erstellen. Wähl eine Karte, dann kannst du sie rechts bearbeiten und sofort erstellen.",
 "자주 쓰는 이미지 프롬프트를 예시 이미지와 함께 모아 둬요. 모델과 카테고리로 골라 보세요.": "Deine bewährten Bild-Prompts mit Beispielbildern. Filtere nach Modell und Kategorie.",
 "플러그인은 스킬 + MCP + 명령을 한 번에 설치하는 묶음이에요.": "Ein Plugin installiert Skills, MCP und Befehle auf einmal als Paket.",
 "에이전트가 쓰는 외부 도구 서버예요. 플러그인은 스킬·MCP를 묶어서 한 번에 설치해요.": "Externe Tool-Server, die Agenten nutzen. Plugins bündeln Skills und MCP und installieren sie auf einmal.",
 "이런 요청이 있었어요": "Diese Anfragen gab es",
 "AI가 두 SKILL.md를 하나로 써 줘요": "Die KI schreibt die beiden SKILL.md zu einer zusammen",
