 "할 일을 모두 펼쳤어요. 줄을 누르면 그 화면으로 가요.": "Alle Aufgaben sind aufgeklappt. Klicke auf eine Zeile, um zu diesem Bildschirm zu gehen.",
 "어젯밤 기억을 살펴보고 정리할 것을 골랐어요. 고르기 전엔 아무것도 바뀌지 않아요.": "Ich habe mir die Erinnerungen von gestern Abend angesehen und ausgewählt, was aufgeräumt werden kann. Solange du nichts auswählst, ändert sich nichts.",
