 "새 버전": "Neue Version",
 "AI가 대화에서 새로 뽑은 기억이에요. 저장할지 버릴지 정해 주세요.": "Neue Erinnerungen, die die KI aus Gesprächen gezogen hat. Entscheide, ob du sie speicherst oder verwirfst.",
 "이미 있는 기억과 다른 내용이 들어왔어요. 어느 쪽이 맞는지 골라 주세요.": "Es ist Inhalt eingegangen, der von einer vorhandenen Erinnerung abweicht. Wähle, welche stimmt.",
 "확인해 주세요": "Bitte prüfen",
 "같은 작업에서 이어서 쓰인 스킬 순서예요. 관찰한 것일 뿐, 실행 허가는 아니에요.": "Reihenfolge von Skills, die in derselben Aufgabe nacheinander genutzt wurden. Das ist nur eine Beobachtung, keine Erlaubnis zur Ausführung.",
 "대화에서 관찰한 사용자 성향이에요. 지시나 실행 승인으로 쓰지 않아요.": "Beobachtete Vorlieben des Nutzers aus Gesprächen. Sie gelten nie als Anweisung oder Freigabe zur Ausführung.",
 "작업하면서 얻은 해석이에요. 사실이나 실행 승인으로 쓰지 않아요.": "Deutungen, die bei der Arbeit entstanden sind. Sie gelten nie als Fakten oder Freigabe zur Ausführung.",
 "정한 시각에 쓰이던 기억을 그대로 보여 줘요. 지금 지시로는 쓰지 않아요.": "Zeigt die Erinnerungen genau so, wie sie zum gewählten Zeitpunkt genutzt wurden. Sie gelten jetzt nicht als Anweisung.",
 "에이전트와 나눈 대화예요. 7일 보관하고, 기억이 실제로 쓰이면 그때부터 다시 7일을 세요.": "Gespräche mit Agenten. Sie werden 7 Tage aufbewahrt; wird eine Erinnerung tatsächlich genutzt, beginnen die 7 Tage von vorn.",
 "항상 적용": "Immer angewendet",
