 "같은 평가 과제로 두 버전을 돌려 점수·비용·시간을 비교해요.": "Beide Versionen laufen mit derselben Testaufgabe, dann werden Punktzahl, Kosten und Zeit verglichen.",
 "검토·승인": "Prüfen & freigeben",
 "무엇이 바뀌었나요": "Was sich geändert hat",
 "후보 버전의 원문과 평가를 보고 승인하거나 제외해요.": "Sieh dir den Originaltext und die Bewertung der Kandidatenversion an und gib sie dann frei oder schließe sie aus.",
