 "스킬 설명에 쓰는 때가 적혀 있지 않아요.": "In der Skill-Beschreibung steht nicht, wann er genutzt wird.",
 "개선 목표": "Ziel der Verbesserung",
 "이만큼 좋아지면 통과예요": "So viel muss besser werden, um zu bestehen",
 "지금 상태": "Aktueller Stand",
 "평가 서버에서 비교해요": "Vergleich auf dem Testserver",
 "앱의 API 연결과 같은 평가 서버에서, 등록된 고정 과제와 실행 조건만 써요. 실행만으로 승인·적용되지는 않아요.": "Es werden nur registrierte feste Aufgaben und Ausführungsbedingungen auf demselben Testserver wie die API-Verbindung der App genutzt. Ausführen allein gibt nichts frei und wendet nichts an.",
 "후보 버전을 승인할까요?": "Kandidatenversion freigeben?",
 "시험 상태": "Teststatus",
 "정한 기간만 시험해요": "Nur für einen festen Zeitraum testen",
 "기본 버전은 그대로 두고, 고른 프로그램에서만 승인된 후보를 써요. 끝나는 시각이 지나면 기본 버전으로 돌아가요.": "Die Standardversion bleibt unverändert; nur die gewählten Programme nutzen den freigegebenen Kandidaten. Nach der Endzeit gilt wieder die Standardversion.",
 "연결이 끊겨도 요청은 보관돼요. 다시 연결한 뒤 상태를 확인하세요.": "Anfragen bleiben auch bei unterbrochener Verbindung gespeichert. Prüfe den Status nach dem erneuten Verbinden.",
 "이 스킬": "Dieser Skill",
