 "그룹을 바꿨어요. 저장해야 적용돼요.": "Gruppen geändert. Speichere, damit es gilt.",
 "그룹 저장": "Gruppen speichern",
 "자동으로 묶은 그룹": "Automatisch gebildete Gruppe",
