 "이 그룹 쓰기": "Diese Gruppe verwenden",
 "에이전트는 모델 이름에 위 group/… 을 넣어 이 그룹을 써요.": "Agenten nutzen diese Gruppe, indem sie das obige group/… als Modellnamen angeben.",
 "같은 모델이 여러 계정에 있어 서버가 자동으로 묶었어요. 고치려면 그룹으로 만들어요.": "Dasselbe Modell ist in mehreren Konten vorhanden, daher hat der Server es automatisch gruppiert. Erstelle daraus eine Gruppe, um es zu bearbeiten.",
 "그룹으로 만들기": "Als Gruppe erstellen",
