 "AI가 새로 만든 초안이에요. 검토해 주세요.": "Die KI hat diesen neuen Entwurf erstellt. Bitte prüfe ihn.",
 "검토됨으로 표시": "Als geprüft markieren",
 "고치면 바로 검토된 글이 되고, 잠겨서 AI가 더 고치지 않아요.": "Wenn du etwas änderst, gilt der Text sofort als geprüft und wird gesperrt, damit die KI ihn nicht weiter ändert.",
