 "자료": "Eintrag",
 "아직 없어요. 늘 알아야 하는 결정·스킬·문서를 넣어 두면, 부를 때마다 검색보다 먼저 들어가요.": "Noch nichts da. Füge Entscheidungen, Skills oder Dokumente hinzu, die immer bekannt sein sollen – sie kommen bei jedem Aufruf noch vor der Suche dazu.",
 "전체=다 넣기 · 요약=줄여서 넣기 · 참조=제목만 넣고 필요할 때 읽기 · 고정=그 버전만, 최신=바뀌면 따라가기": "Komplett = alles einfügen · Kurzfassung = gekürzt · Verweis = nur Titel, bei Bedarf lesen · Fest = nur diese Version, Neueste = folgt Änderungen",
 "나중에": "Später",
 "설정됨": "Eingerichtet",
 "토큰 파일이 깨졌거나 다른 사용자도 읽을 수 있게 열려 있어요. 다시 만들면 고쳐져요.": "Die Token-Datei ist beschädigt oder für andere Nutzer lesbar. Wenn du ein neues Token erstellst, ist das behoben.",
 "모델 중계기": "Modell-Gateway",
 "중계기 토큰을 다시 만들까요? 에이전트 설정에 새 토큰을 넣어요.": "Gateway-Token neu erstellen? Das neue Token wird in die Agent-Einstellungen eingetragen.",
 "새 토큰을 만들고 에이전트 설정에 넣었어요. 중계기를 다시 켜면 예전 토큰은 막혀요.": "Das neue Token wurde erstellt und in die Agent-Einstellungen eingetragen. Sobald du das Gateway neu startest, wird das alte Token gesperrt.",
 "새 토큰을 만들었어요. 에이전트 설정에는 못 넣었어요 — 진단에서 고치기를 눌러 주세요.": "Das neue Token wurde erstellt. Es konnte aber nicht in die Agent-Einstellungen eingetragen werden – tippe in der Diagnose auf „Beheben“.",
 "토큰을 만들지 못했어요.": "Das Token konnte nicht erstellt werden.",
