 "확정": "Bestätigt",
 "스킬 판정": "Skill-Bewertung",
 "route_skills가 고른 스킬과 판정기예요. 규칙은 판정 모델 없이 검색 1위를 고른 것이고, 확신 낮음은 판정기가 고르지 않은 것이에요.": "Die von route_skills gewählten Skills und wer sie bewertet hat. „Regel“ heißt: Der erste Suchtreffer wurde ohne Bewertungsmodell gewählt. „Geringe Sicherheit“ heißt: Der Bewerter hat nichts gewählt.",
