 "Claude Code 호출": "Claude Code-Aufrufe",
 "본대화와 부속 호출을 따로 세요": "Hauptgespräch und Nebenaufrufe werden getrennt gezählt",
 "부속 호출": "Nebenaufrufe",
 "부속 호출은 Claude Code가 제목·요약·대화 압축 같은 일로 따로 보내는 호출이에요. 비용은 공개 가격으로 셈한 추정이에요.": "Nebenaufrufe sind zusätzliche Aufrufe, die Claude Code für Titel, Zusammenfassungen, Gesprächskomprimierung und Ähnliches sendet. Die Kosten sind Schätzungen auf Basis öffentlicher Preise.",
