 "주제 요약": "Themenzusammenfassungen",
 "새로 들어온 기억이 이미 있는 기억과 비슷해요. AI 제안을 보고 저장할지, 합칠지, 건너뛸지 골라 주세요.": "Neue Erinnerungen ähneln schon vorhandenen. Sieh dir den KI-Vorschlag an und entscheide, ob du speichern, zusammenführen oder überspringen willst.",
 "비슷한 기억을 주제로 묶고 AI가 요약해요. 요약이 바뀌면 바로 쓰지 않고 먼저 확인을 받아요.": "Ähnliche Erinnerungen werden zu Themen gruppiert und von der KI zusammengefasst. Eine geänderte Zusammenfassung wird erst nach deiner Bestätigung verwendet.",
 "새 주제": "Neues Thema",
 "두 요약 합치기": "Zwei Zusammenfassungen zusammenführen",
 "기존과 충돌": "Widerspricht dem Bestehenden",
 "새 규칙": "Neue Regel",
 "작은 보완 누적": "Kleine Ergänzungen angesammelt",
 "직접 요청": "Auf deine Anfrage",
 "최근 대화에서 바뀐 습관이 보여서 AI가 요약 후보를 만들었어요. 바꿀까요?": "In letzten Gesprächen zeigt sich eine geänderte Gewohnheit, deshalb hat die KI einen neuen Zusammenfassungsentwurf erstellt. Umstellen?",
 "새 규칙이 생겨서 AI가 요약 후보를 만들었어요. 바꿀까요?": "Es gibt eine neue Regel, deshalb hat die KI einen neuen Zusammenfassungsentwurf erstellt. Umstellen?",
 "작은 보완이 쌓여서 AI가 요약 후보를 만들었어요. 바꿀까요?": "Kleine Ergänzungen haben sich angesammelt, deshalb hat die KI einen neuen Zusammenfassungsentwurf erstellt. Umstellen?",
 "요청하신 대로 요약 후보를 다시 만들었어요. 바꿀까요?": "Wie gewünscht wurde der Zusammenfassungsentwurf neu erstellt. Umstellen?",
