 "바탕 기억이 수정됨": "Quell-Erinnerungen geändert",
 "그 뒤 승인된 기억 있음": "Seitdem freigegebene Erinnerungen vorhanden",
 "바탕 기억이 대체됨": "Eine Quell-Erinnerung wurde ersetzt",
 "요약을 불러오는 중…": "Zusammenfassungen werden geladen…",
 "검색과 맞는 주제가 없어요.": "Kein Thema passt zu deiner Suche.",
 "아직 주제 요약이 없어요. 승인된 기억이 쌓이면 밤사이 제안돼요.": "Noch keine Themenzusammenfassungen. Sobald genug freigegebene Erinnerungen da sind, werden sie über Nacht vorgeschlagen.",
 "요약을 불러오지 못했어요. 새로고침하면 다시 불러와요.": "Die Zusammenfassungen konnten nicht geladen werden. Aktualisiere, um es noch einmal zu versuchen.",
 "여기에 표시할 요약이 없어요.": "Hier gibt es keine Zusammenfassungen anzuzeigen.",
 "· 최대 개수에 닿아서 합치기 제안이 나올 수 있어요": "· Das Maximum ist erreicht, deshalb können Zusammenführungsentwürfe erscheinen",
 "나에 대한 요약": "Zusammenfassung über mich",
 "바탕 기억이 바뀌거나 지워져 쓸 수 없어요. 다음 실행 때 다시 제안돼요.": "Die Quell-Erinnerungen wurden geändert oder gelöscht, deshalb ist sie nicht nutzbar. Beim nächsten Durchlauf wird sie erneut vorgeschlagen.",
 "아직 쓰는 요약은 없어요. 후보를 확인해 주세요.": "Noch keine Zusammenfassung in Gebrauch. Bitte prüfe den Entwurf.",
 "아직 요약이 없어요. 나에 대한 기억이 승인되면 제안돼요.": "Noch keine Zusammenfassung. Sie wird vorgeschlagen, sobald Erinnerungen über dich freigegeben sind.",
 "주제를 고르세요": "Wähle ein Thema",
 "비슷한 기억을 묶은 요약이에요. 사실이나 지시가 아니라 참고 자료로 쓰여요.": "Eine Zusammenfassung ähnlicher Erinnerungen. Sie dient als Referenz, nicht als Fakt oder Anweisung.",
 "지금 요약": "Aktuelle Zusammenfassung",
 "묶인 기억": "Gruppierte Erinnerungen",
 "질문이 이 주제와 맞을 때": "Wenn eine Frage zu diesem Thema passt",
 "모든 에이전트 · 참고 자료로": "Alle Agents · als Referenz",
 "승인된 기억으로 AI가 새 주제를 묶었어요. 이 요약을 쓸까요?": "Die KI hat freigegebene Erinnerungen zu einem neuen Thema gruppiert. Diese Zusammenfassung verwenden?",
 "비슷한 두 요약을 하나로 합치자는 후보예요. 합치면 두 요약은 이전 버전으로 남아요.": "Ein Entwurf, der zwei ähnliche Zusammenfassungen zu einer vereint. Nach dem Zusammenführen bleiben beide als ältere Versionen erhalten.",
 "AI가 요약을 고쳤어요. 이 후보로 바꿀까요?": "Die KI hat die Zusammenfassung überarbeitet. Zu diesem Entwurf wechseln?",
 "모아보기 · 나에 대한 요약": "Gruppiert · Über mich",
 "승인하면 새 세션 시작 때 에이전트에게 참고 자료로 전달돼요(지시가 아님).": "Wenn du zustimmst, bekommen Agenten sie beim Start einer neuen Sitzung als Referenz (nicht als Anweisung).",
 "AI가 요약 후보를 만들었어요. 바꿀까요?": "Die KI hat einen neuen Zusammenfassungsentwurf erstellt. Wechseln?",
