 "길이": "Länge",
 "변경 이력": "Änderungsverlauf",
 "지금 쓰는 중": "Aktuell in Gebrauch",
 "이전 버전": "Ältere Version",
 "· 승인": "· genehmigt",
 "지시처럼 보이는 문장 포함": "Enthält anweisungsähnliche Sätze",
 "버리는 이유 (선택)": "Grund fürs Verwerfen (optional)",
 "묶인 기억이 없어요.": "Keine gruppierten Erinnerungen.",
 "읽을 수 없는 기억이에요 (지워졌거나 바뀜)": "Diese Erinnerung ist nicht lesbar (gelöscht oder geändert)",
 "새로 묶임": "neu gruppiert",
 "새": "Neu",
 "다음 야간 실행 때 새 후보로 나와요.": "Beim nächsten nächtlichen Lauf erscheint ein neuer Entwurf.",
 "이 계정은 요약을 다시 만들 수 없어요.": "Mit diesem Konto kannst du Zusammenfassungen nicht neu erstellen.",
 "나에 대한 요약을 바꿨어요. 새 세션부터 쓰여요.": "Die Zusammenfassung über dich wurde geändert. Sie gilt ab der nächsten Sitzung.",
 "요약을 바꿨어요. 이전 버전은 이력에 남아요.": "Die Zusammenfassung wurde geändert. Die ältere Version bleibt im Verlauf.",
 "바탕이 바뀌었거나 주제 수가 꽉 차서 처리하지 못했어요. 새로 불러왔어요. (꽉 찼다면 합치기 후보를 먼저 승인하세요)": "Das ging nicht, weil sich die Grundlage geändert hat oder das Themenlimit erreicht ist. Neu geladen. (Wenn das Limit erreicht ist, genehmige zuerst einen Zusammenführungsentwurf.)",
 "이 계정은 요약을 승인할 수 없어요.": "Mit diesem Konto kannst du Zusammenfassungen nicht genehmigen.",
 "비슷한 기억 없음": "Keine ähnliche Erinnerung",
 "읽을 수 없는 후보예요": "Dieser Entwurf ist nicht lesbar",
 "제안을 불러오는 중…": "Vorschläge werden geladen…",
 "검색과 맞는 제안이 없어요.": "Keine Vorschläge passend zur Suche.",
 "AI 제안은 바로 적용하지 않아요. 고르면 그때 저장돼요.": "KI-Vorschläge werden nicht sofort angewendet. Gespeichert wird erst, wenn du auswählst.",
 "제안을 고르세요": "Wähle einen Vorschlag",
 "AI가 새 후보를 이미 있는 기억과 견줘 본 결과예요. 고르기 전엔 아무것도 바뀌지 않아요.": "Die KI hat einen neuen Entwurf mit vorhandenen Erinnerungen verglichen. Nichts ändert sich, bevor du auswählst.",
 "비슷한 기억이 이미 있어요": "Eine ähnliche Erinnerung gibt es schon",
 "새 기억으로 저장 제안": "Vorschlag: als neue Erinnerung speichern",
 "이미 있는 기억과 같아요": "Entspricht einer vorhandenen Erinnerung",
 "바뀜": "Geändert",
 "이미 있는 기억과 같음 → 건너뛰기 제안": "Entspricht einer vorhandenen Erinnerung → Vorschlag: überspringen",
 "후보나 대상 기억이 그사이 바뀌어서 이 제안은 쓸 수 없어요. 무시하거나 새로 저장 목록에서 직접 골라 주세요.": "Der Entwurf oder die Zielerinnerung hat sich inzwischen geändert, daher ist dieser Vorschlag nicht nutzbar. Ignoriere ihn oder entscheide selbst in der Liste „Neu gespeichert“.",
 "지금 내용을 읽지 못했어요. 다시 열어 주세요.": "Der aktuelle Inhalt konnte nicht gelesen werden. Bitte öffne ihn erneut.",
 "수락": "Annehmen",
 "고쳐서 수락": "Bearbeiten und annehmen",
 "고친 내용으로 수락": "Mit meiner Änderung annehmen",
 "이미 있는 기억": "Vorhandene Erinnerung",
 "대상 기억": "Zielerinnerung",
 "합친 뒤": "Nach dem Zusammenführen",
 "기존 기억에서 빠지는 말은 빨간 취소선, 새로 들어오는 말은 초록으로 보여요.": "Wörter, die aus der bisherigen Erinnerung entfallen, sind rot durchgestrichen, neu hinzukommende grün.",
 "이렇게 하면": "Das passiert",
 "대상 기억은 이력으로 남고, 새 내용이 그 자리를 대신해요": "Die Zielerinnerung bleibt im Verlauf und der neue Text ersetzt sie",
 "새 내용을 기억으로 저장해요": "Speichert den neuen Text als Erinnerung",
 "새 후보를 거절해요 · 지우지 않고 기록은 남아요": "Lehnt den neuen Entwurf ab · wird nicht gelöscht, der Eintrag bleibt",
 "제안만 닫혀요 · 후보는 새로 저장 목록에 그대로 남아요": "Nur der Vorschlag wird geschlossen · der Entwurf bleibt in „Neu gespeichert“",
 "제안을 닫았어요. 후보는 새로 저장 목록에 남아요.": "Vorschlag geschlossen. Der Entwurf bleibt in „Neu gespeichert“.",
 "후보를 건너뛰었어요.": "Entwurf übersprungen.",
 "처리했어요.": "Erledigt.",
 "후보나 대상 기억이 바뀌어 이 제안은 낡았어요. 새로 불러왔어요.": "Der Entwurf oder die Zielerinnerung hat sich geändert, daher ist dieser Vorschlag veraltet. Neu geladen.",
 "이 계정은 제안을 처리할 수 없어요.": "Mit diesem Konto kannst du Vorschläge nicht bearbeiten.",
 "복사했어요.": "Kopiert.",
 "복사하지 못했어요.": "Kopieren fehlgeschlagen.",
 "잘라내기": "Ausschneiden",
