 "링크 복사": "Link kopieren",
 "Ctrl+V로 붙여넣어 주세요.": "Bitte füge mit Strg+V ein.",
 "부르는 곳": "Aufrufer",
 "고친 내용은 버렸지만 지금 기억은 지우지 못했어요. 기억 목록에서 직접 지워 주세요.": "Die Änderung wurde verworfen, aber die aktuelle Erinnerung konnte nicht gelöscht werden. Bitte lösche sie selbst in der Erinnerungsliste.",
 "개인": "Privat",
