 "관측 시각": "Beobachtet um",
 "기록되지 않았어요.": "Nicht erfasst.",
 "적용 시점": "Gilt ab",
 "불확실성": "Unsicherheit",
 "별도 설명이 없어요.": "Keine weitere Erläuterung.",
 "관측 없음": "Keine Beobachtungen",
 "이 버전의 기억이 도움이 됐는지 아직 확인되지 않았어요.": "Ob diese Version der Erinnerung geholfen hat, wurde noch nicht geprüft.",
 "관측에서 실패": "In Beobachtung fehlgeschlagen",
 "사용자 평가 또는 자동 검사에 실패 결과가 있어요. 근거와 내용을 확인해 주세요.": "Eine Nutzerbewertung oder automatische Prüfung ist fehlgeschlagen. Bitte prüfe Beleg und Inhalt.",
 "관측에서 통과": "In Beobachtung bestanden",
 "사용자 평가 또는 자동 검사에 통과했어요. 모든 상황에서 유용하다는 뜻은 아니에요.": "Eine Nutzerbewertung oder automatische Prüfung wurde bestanden. Das heißt nicht, dass es in jeder Situation nützlich ist.",
 "판정 없는 관측": "Beobachtung ohne Urteil",
 "관측은 남았지만 통과·실패 판정은 아직 없어요.": "Es gibt eine Beobachtung, aber noch kein Urteil „bestanden“ oder „fehlgeschlagen“.",
 "모델 자기평가만 있음": "Nur Selbstbewertung des Modells",
 "만든 모델의 자기평가예요. 독립된 사용 결과는 아직 없어요.": "Das ist die Selbstbewertung des erstellenden Modells. Ein unabhängiges Nutzungsergebnis gibt es noch nicht.",
 "관측 대기": "Warten auf Beobachtung",
 "관측 기록됨": "Beobachtung erfasst",
 "추적 기록 없음": "Kein Verlauf",
 "기억 평가": "Erinnerungsbewertung",
 "관측 결과를 불러오는 중…": "Beobachtungen werden geladen…",
 "평가 추적": "Bewertungsverlauf",
 "독립된 관측": "Unabhängige Beobachtung",
 "Claude API 월 예산": "Monatsbudget für Claude API",
 "예산을 불러오는 중…": "Budget wird geladen…",
 "월 전체": "Gesamter Monat",
 "일반 처리": "Allgemeine Verarbeitung",
 "오늘 목표": "Tagesziel",
 "오늘 상한": "Tageslimit",
 "미정산 예약": "Nicht abgerechnete Reservierungen",
 "사용 확정액과 미정산 예약을 함께 계산해요. 실제 청구 금액과 다를 수 있어요.": "Berücksichtigt bestätigte Ausgaben und nicht abgerechnete Reservierungen. Kann vom tatsächlichen Rechnungsbetrag abweichen.",
 "오늘 목표를 넘었어요. 목표 초과만으로 처리를 차단하지 않으며 월 예산과 별도 설정한 상한은 계속 적용해요.": "Das Tagesziel wurde überschritten. Allein deshalb wird die Verarbeitung nicht blockiert; das Monatsbudget und ein separat festgelegtes Limit gelten weiterhin.",
 "오늘 목표는 지출 추이를 보는 기준이에요. 월 예산과 별도 설정한 상한은 계속 적용해요.": "Das Tagesziel dient nur als Richtwert für den Ausgabenverlauf. Das Monatsbudget und ein separat festgelegtes Limit gelten weiterhin.",
 "예산 다시 조회": "Budget neu abrufen",
 "생성 모델 기록": "Erzeugendes Modell",
 "이 기록을 생성한 모델이에요. 모델 이름만으로 내용의 정확성이나 현재 기본 모델을 판단하지 않아요.": "Das Modell, das diesen Eintrag erzeugt hat. Der Modellname allein sagt nichts über die Richtigkeit oder das aktuelle Standardmodell aus.",
 "시험 진행 중": "Test läuft",
 "실행과 독립 평가가 모두 확인되어야 다음 단계로 넘어가요.": "Erst wenn Ausführungen und unabhängige Bewertung bestätigt sind, geht es zum nächsten Schritt.",
 "시험 조건 변경": "Testbedingungen geändert",
 "근거나 기준판이 달라져 현재 시험 후보를 사용할 수 없어요.": "Beleg oder Referenz haben sich geändert, daher kann der aktuelle Testkandidat nicht verwendet werden.",
 "종료는 시험 통과를 뜻하지 않아요.": "Beenden bedeutet nicht, dass der Test bestanden wurde.",
 "회귀 관측으로 시험 중단": "Test nach Verschlechterung gestoppt",
 "문제가 관측되어 시험 후보 사용이 중단됐어요.": "Es wurde ein Problem beobachtet, daher wird der Testkandidat nicht mehr verwendet.",
 "시험 기간 종료": "Testzeitraum beendet",
 "기간이 끝났다는 이유만으로 성공 처리하지 않아요.": "Wir werten einen Versuch nicht als Erfolg, nur weil die Zeit abgelaufen ist.",
 "기본 버전으로 적용됨": "Als Standardversion angewendet",
 "승격 뒤 회귀 여부는 계속 별도 관측으로 확인해요.": "Ob nach der Beförderung etwas schlechter geworden ist, prüfen wir weiterhin separat.",
 "회귀 버전 차단 · 복구 미완료": "Fehlerhafte Version blockiert · Wiederherstellung unvollständig",
 "문제가 있는 버전은 차단됐지만 기준판 복구는 아직 확인되지 않았어요.": "Die fehlerhafte Version ist blockiert, aber die Wiederherstellung der Basisversion ist noch nicht bestätigt.",
 "기준판으로 복구됨": "Auf Basisversion zurückgesetzt",
 "서버에서 기준판 선택을 확인했어요. 이미 실행 중인 작업의 복구를 뜻하지는 않아요.": "Der Server hat bestätigt, dass die Basisversion ausgewählt ist. Bereits laufende Aufgaben werden dadurch nicht wiederhergestellt.",
 "자동 확인 중": "Wird automatisch geprüft",
 "다음 확인 대기": "Warten auf nächste Prüfung",
 "자동 확인 실패 · 재확인 필요": "Automatische Prüfung fehlgeschlagen · erneut prüfen",
 "확인 작업 종료": "Prüfaufgabe beendet",
 "현재 처리 상태를 확인하는 중…": "Aktueller Status wird geprüft …",
 "독립 평가 결과는 이 조회에서 확인되지 않아요.": "Unabhängige Bewertungsergebnisse werden bei dieser Abfrage nicht angezeigt.",
 "자동 확인 작업이 등록되어 있지 않아요.": "Es ist keine automatische Prüfaufgabe eingerichtet.",
 "처리 상태를 확인하지 못했어요": "Status konnte nicht geprüft werden",
 "권한이나 서버 상태를 확인한 뒤 다시 조회해 주세요.": "Prüfe deine Berechtigungen oder den Serverstatus und lade dann erneut.",
 "자동 처리 상태": "Status der automatischen Verarbeitung",
 "처리 상태 다시 조회": "Status neu laden",
 "템플릿·설정으로 만들기": "Aus Vorlage oder Einstellungen erstellen",
 "AI 답을 읽지 못했어요. 다시 보내 주세요.": "Die Antwort der KI konnte nicht gelesen werden. Bitte sende sie erneut.",
 "제목없음": "Ohne Titel",
 "토큰 줄이기": "Tokens sparen",
 "안전": "Sicherheit",
 "끝난 기준과 결과물": "Erledigt, wenn … und Ergebnis",
 "자세히 · 끝난 기준, 실행 설정": "Mehr · Erledigt-Kriterium, Ausführungseinstellungen",
 "자세히 · 끝난 기준, 실행 설정, 관리": "Mehr · Erledigt-Kriterium, Ausführungseinstellungen, Verwalten",
 "크림": "Creme",
