 "배경색": "Hintergrundfarbe",
 "아바타": "Avatar",
 "아바타 고르기": "Avatar auswählen",
 "모델 아이콘 쓰기": "Modell-Symbol verwenden",
 "답에 보였는지": "Ob es in der Antwort vorkam",
 "아직 서버가 답에 보였는지 기록을 보내지 않았어요.": "Der Server hat noch keine Angaben dazu gesendet, ob Erinnerungen in Antworten vorkamen.",
 "질문할 때 찾아 넣은 기억의 문구가 답에 보였는지만 세요. 실제 활용 여부는 측정하지 않았고, 읽지 못한 대화 수는 이 통계에서 알 수 없어요.": "Gezählt wird nur, ob der Wortlaut der Erinnerungen, die bei der Frage gefunden wurden, in der Antwort vorkam. Ob sie wirklich genutzt wurden, wird nicht gemessen, und die Zahl der ungelesenen Unterhaltungen ist in dieser Statistik nicht enthalten.",
 "답에 보인 기억이 아직 없어요.": "Noch keine Erinnerungen, die in Antworten vorkamen.",
 "답에 안 보여 확인할 기억": "Erinnerungen zum Prüfen, die in Antworten nicht vorkamen",
 "답에 안 보임": "Nicht in der Antwort",
 "최근 호출 없음": "Zuletzt nicht abgerufen",
 "기억이 답에 보였는지는 PC 수집기가 보고하면 여기에 보여요. 실제 활용 여부는 측정하지 않아요.": "Ob Erinnerungen in Antworten vorkamen, zeigt dir hier der PC-Collector an, sobald er es meldet. Ob sie wirklich genutzt wurden, wird nicht gemessen.",
 "답에 안 보임 · 직접 검토": "Nicht in der Antwort · selbst prüfen",
 "답에 보인 비율": "Anteil in Antworten",
 "답에 보임": "In der Antwort",
 "종류별로 답에 보인 비율": "Anteil in Antworten nach Art",
 "전달한 기억 중 답에 보인 비율": "Anteil der übermittelten Erinnerungen, die in Antworten vorkamen",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보여요. 직접 확인해 주세요": "Das Prüfdatum ist überschritten, oder sie wurden zuletzt selten abgerufen oder kamen selten in Antworten vor. Bitte prüfe sie selbst.",
 "승인 기록": "Genehmigungsprotokoll",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보이는 기억이에요. 실제 활용 여부와는 구분해요.": "Das sind Erinnerungen, deren Prüfdatum überschritten ist oder die zuletzt selten abgerufen wurden oder selten in Antworten vorkamen. Das ist etwas anderes als die tatsächliche Nutzung.",
 "재검토 예정일 지남": "Prüfdatum überschritten",
 "확인하기": "Prüfen",
 "펼치면 서로 다른 원문 발화 수를 확인해요. 횟수는 승인이나 신뢰 점수가 아니에요.": "Klappe auf, um die Zahl unterschiedlicher Original-Äußerungen zu sehen. Die Anzahl ist weder eine Genehmigung noch ein Vertrauenswert.",
 "각 문장의 조건과 예외를 확인하고 항목별로 결정해 주세요.": "Prüfe Bedingungen und Ausnahmen jedes Satzes und entscheide dann für jeden Eintrag einzeln.",
 "원문 근거를 확인하는 중…": "Originalbelege werden geprüft …",
 "재검토 예정일이 지났어요": "Das Prüfdatum ist überschritten",
 "대화에서 기억할 만한 내용을 찾아요. 저장할지는 사람이 정해요.": "Sucht in Unterhaltungen nach Dingen, die man sich merken sollte. Ob sie gespeichert werden, entscheidet ein Mensch.",
 "재검토 예정일이 지났어요. 내용이 아직 맞는지 직접 확인해 주세요.": "Das Prüfdatum ist überschritten. Bitte prüfe selbst, ob der Inhalt noch stimmt.",
 "최근 30일 동안 검색으로 전달된 기록이 없어요. 실제 활용 여부와 내용의 필요성은 따로 확인해 주세요.": "In den letzten 30 Tagen wurde nichts per Suche übermittelt. Ob es wirklich genutzt wird und der Inhalt noch gebraucht wird, musst du separat prüfen.",
 "기억 관리": "Erinnerungen verwalten",
 "정정 또는 충돌 검토가 대기 중이에요. 기존 기억이 계속 전달될 수 있으니 먼저 확인해 주세요.": "Eine Korrektur oder Konfliktprüfung steht aus. Die bisherige Erinnerung wird eventuell weiter übermittelt, bitte prüfe sie zuerst.",
 "다음 재검토": "Nächste Prüfung",
 "예정일 없음": "Kein Datum geplant",
 "사용 종료": "Nutzung endet",
 "만료일 없음": "Kein Ablaufdatum",
 "재검토 예정일은 삭제·자동 승인·보관 연장과 별개예요.": "Das Prüfdatum ist unabhängig von Löschung, automatischer Genehmigung und Verlängerung der Aufbewahrung.",
 "원본 보관 상태는 별도로 확인할 수 있어요.": "Den Aufbewahrungsstatus des Originals kannst du separat prüfen.",
 "원본 보관 확인": "Aufbewahrung des Originals prüfen",
 "· 일부만 확인": "· nur teilweise geprüft",
 "원본 상태를 확인하지 못했어요. 보관 중이라고 간주하지 않아요.": "Der Status des Originals konnte nicht geprüft werden. Wir gehen nicht davon aus, dass es aufbewahrt wird.",
 "재검토 예정일": "Prüfdatum",
 "재검토 예정일을 변경했어요.": "Prüfdatum geändert.",
 "예정일 저장": "Datum speichern",
 "앞으로의 날짜를 선택해 주세요.": "Wähle ein Datum in der Zukunft.",
 "예정일 해제": "Datum entfernen",
 "원문 확인": "Original prüfen",
 "AI가 쓴 이유와 실제 대화는 다를 수 있어요. 저장하기 전에 원문을 확인해 보세요.": "Die Begründung der KI und die tatsächliche Unterhaltung können sich unterscheiden. Prüfe das Original, bevor du speicherst.",
 "원문 보기": "Original ansehen",
 "원문 근거를 확인하지 못했어요. 확인된 내용으로 간주하지 않아요.": "Der Originalbeleg konnte nicht geprüft werden. Er gilt nicht als bestätigt.",
 "AI가 제안한 이유": "Warum die KI das vorgeschlagen hat",
 "사람이 확인하고 저장했어요": "Ein Mensch hat es geprüft und gespeichert",
 "누가 언제 확인했는지 기록이 남아 있어요.": "Wer es wann geprüft hat, ist protokolliert.",
 "사람이 저장 여부를 결정해 주세요.": "Bitte entscheide, ob das gespeichert werden soll.",
 "예전 방식으로 저장됨": "Auf die alte Art gespeichert",
 "예전에 저장돼 사람이 직접 확인했다는 기록이 없어요. 쓰는 데는 문제없어요.": "Es wurde früher gespeichert, daher gibt es keinen Eintrag, dass ein Mensch es geprüft hat. Du kannst es trotzdem ganz normal nutzen.",
 "확인 기록 없음 (예전 방식)": "Keine Prüfung protokolliert (alte Art)",
 "누가 확인했는지 기록이 남지 않았어요. 쓰는 데는 문제없어요.": "Es gibt keinen Eintrag, wer es geprüft hat. Du kannst es trotzdem ganz normal nutzen.",
