 "처리 기록을 읽지 못했어요. 완료로 간주하지 않아요.": "Das Verarbeitungsprotokoll konnte nicht gelesen werden. Wir gehen nicht von „abgeschlossen“ aus.",
 "이 앱에서 접수한 삭제 요청 기록이 없어요.": "Diese App hat keine Löschanfragen aufgezeichnet.",
 "삭제 요청을 접수했어요. 정리·백업 처리 상태는 설정의 삭제 처리 내역에서 확인해 주세요.": "Die Löschanfrage ist eingegangen. Den Status von Bereinigung und Backup findest du in den Einstellungen unter „Löschverlauf“.",
 "보관소 점검은 읽기 전용이며 외부 백업과 사용자 앱 사본은 별도 확인이 필요해요.": "Die Archivprüfung ist schreibgeschützt. Externe Backups und Kopien in deinen Apps musst du separat prüfen.",
 "보관소 잔여 점검": "Archiv auf Reste prüfen",
 "시간 제한이나 읽기 오류로 점검을 마치지 못했어요. 잔여 데이터가 없다고 확인한 것은 아니에요.": "Die Prüfung wurde wegen eines Zeitlimits oder eines Lesefehlers nicht beendet. Es ist nicht bestätigt, dass keine Restdaten vorhanden sind.",
 "점검하지 못했어요. 삭제 완료로 간주하지 않아요.": "Die Prüfung ist fehlgeschlagen. Wir gehen nicht von „Löschung abgeschlossen“ aus.",
