 "후보나 대상 기억이 바뀌어 이 제안은 낡았어요.": "Der Kandidat oder die Ziel-Erinnerung hat sich geändert, deshalb ist dieser Vorschlag veraltet.",
 "이 세션을 지울까요?": "Diese Sitzung löschen?",
 "세션과 보관된 대화가 지워지고 되돌릴 수 없어요. 에이전트의 원래 파일은 그대로 남고, 이 대화를 출처로 둔 기억은 내용은 남고 출처 연결만 사라져요.": "Die Sitzung und das archivierte Gespräch werden gelöscht und lassen sich nicht wiederherstellen. Die Originaldateien des Agents bleiben erhalten. Erinnerungen, die dieses Gespräch als Quelle haben, behalten ihren Inhalt, verlieren aber die Quellenverknüpfung.",
 "불러온 횟수": "Abrufe",
 "끝나면 알려줌을 고르면 n8n이 callback_url로 결과를 돌려줄 때까지 멈춰요. 서버에 공개 주소가 있어야 해요.": "Wenn du „Benachrichtigen, wenn fertig“ wählst, wartet der Lauf, bis n8n das Ergebnis an callback_url zurückschickt. Der Server braucht dafür eine öffentliche Adresse.",
