 "워커 더하기": "Worker hinzufügen",
 "검색 결과": "Suchergebnisse",
 "실행할 때 AI가 일을 몇 개로 나눌지 정하고, 워커 결과를 이 노드가 합쳐요.": "Beim Ausführen entscheidet die KI, in wie viele Teile die Arbeit aufgeteilt wird. Dieser Node führt die Ergebnisse der Worker zusammen.",
 "토큰이 없어 모델 중계기를 쓸 수 없어요. 다시 만들면 에이전트 설정에 바로 넣어요.": "Es gibt keinen Token, daher kann das Modell-Gateway nicht verwendet werden. Wenn du einen neuen erstellst, wird er sofort in die Agent-Einstellungen eingetragen.",
 "지금은 환경 변수에 넣은 토큰을 써요.": "Derzeit wird der Token aus einer Umgebungsvariable verwendet.",
 "중계기 토큰이 없어요. Claude Code·Codex 요청이 라우팅되지 않아요.": "Kein Gateway-Token. Anfragen von Claude Code und Codex werden nicht geroutet.",
 "중계기 토큰 파일에 문제가 있어요. Claude Code·Codex 요청이 라우팅되지 않아요.": "Die Gateway-Token-Datei hat ein Problem. Anfragen von Claude Code und Codex werden nicht geroutet.",
 "대화 수집과 앱 시작을 정해요.": "Lege Gesprächserfassung und App-Start fest.",
 "앱 버전과 Arkism이 기억을 다루는 규칙이에요.": "App-Version und die Regeln, nach denen Arkism mit Erinnerungen umgeht.",
 "이 PC의 Arkism을 쓸지, 서버의 Arkism에 이을지 정해요.": "Lege fest, ob du Arkism auf diesem PC nutzt oder dich mit Arkism auf einem Server verbindest.",
 "바꾸면 바로 적용돼요.": "Änderungen gelten sofort.",
 "스킬과 대화를 읽어 올 에이전트를 정해요.": "Wähle die Agents, aus denen Skills und Chats gelesen werden.",
 "AI 노드가 맡을 역할과 말투예요.": "Rolle und Tonfall, die ein KI-Node übernimmt.",
 "백업·진단·데이터 지우기처럼 자주 바꾸지 않는 설정이에요.": "Einstellungen, die du selten änderst, etwa Backup, Diagnose und Daten löschen.",
 "Arkism이 정한 규칙이라 바꿀 수 없어요.": "Das sind feste Regeln von Arkism und können nicht geändert werden.",
 "말투·보고 방식·작업 절차처럼 늘 지킬 것": "Dinge, die immer gelten sollen, etwa Tonfall, Berichtsweise und Arbeitsschritte",
 "질문과 관련 있을 때만 넣어요": "Wird nur eingefügt, wenn es zur Frage passt",
 "저장소마다 달라요. 미리보기에서 저장소를 골라 보세요.": "Das ist je Repository unterschiedlich. Wähle in der Vorschau ein Repository aus.",
 "저장한 기억은 참고 자료로만 쓰고, 지시로 따르지 않아요.": "Gespeicherte Erinnerungen dienen nur als Referenz und werden nie als Anweisung befolgt.",
 "내가 승인해야 쓰여요": "Wird nur nach deiner Freigabe verwendet",
 "붙여 넣은 글이나 웹 문서에 섞인 지시": "Anweisungen, die in eingefügtem Text oder Webdokumenten stecken",
 "답에 안 드러난 기억 모으기": "Erinnerungen sammeln, die in Antworten nicht auftauchen",
 "7일 동안 3번 넘게 넣었는데 답과 겹치지 않으면 검토 목록에 모아요": "Mehr als 3 Mal in 7 Tagen eingefügt, aber nie in einer Antwort aufgetaucht → landet in der Prüfliste",
 "창 없이 트레이에서 시작해 대화를 계속 저장해요.": "Startet ohne Fenster im Tray und speichert weiter Chats.",
 "서버가 아직 에이전트 목록을 보내지 않았어요. 잠시 뒤 다시 열어 보세요.": "Der Server hat die Agent-Liste noch nicht gesendet. Öffne das gleich noch einmal.",
 "여러 에이전트가 함께 읽는 스킬 폴더예요. 한 번 넣으면 모두 써요.": "Ein Skill-Ordner, den mehrere Agents lesen. Füge einen Skill einmal hinzu, dann nutzen ihn alle.",
 "이 PC에서 찾은 새 에이전트": "Neue Agents auf diesem PC gefunden",
 "‘시스템’은 Windows 설정을 따라요.": "„System“ folgt der Windows-Einstellung.",
 "기억을 뜻으로 찾을 때 써요.": "Wird verwendet, um Erinnerungen nach Bedeutung zu finden.",
 "3시간마다 교훈을 정리하고 검토할 기억을 골라요.": "Fasst alle 3 Stunden Lektionen zusammen und wählt Erinnerungen zur Prüfung aus.",
 "비워 두면 기본 위치를 써요": "Leer lassen, um den Standardort zu verwenden",
 "이 PC에서 Arkism을 실행해요. 인터넷 없이도 돼요.": "Führt Arkism auf diesem PC aus. Funktioniert auch ohne Internet.",
 "서버의 Arkism을 SSH로 이어요. 서버에서 따로 할 일은 없어요.": "Verbindet per SSH mit Arkism auf einem Server. Auf dem Server musst du nichts einrichten.",
 "이미지 프롬프트의 ‘ComfyUI에서 열기’가 여는 주소예요.": "Die Adresse, die „In ComfyUI öffnen“ bei Bild-Prompts öffnet.",
 "화면·정렬·분류 설정을 파일로 옮겨요.": "Überträgt Ansichts-, Sortier- und Kategorieeinstellungen per Datei.",
 "‘유지’한 기억과 정리 설정을 옮겨요. 같은 계정에서만 가져올 수 있어요.": "Überträgt als „Behalten“ markierte Erinnerungen und Aufräum-Einstellungen. Import nur im selben Konto möglich.",
 "스킬 제안 초안과 숨긴 제안을 옮겨요. 같은 계정에서만 가져올 수 있고, 초안 본문이 들어 있어요.": "Überträgt Entwürfe von Skill-Vorschlägen und ausgeblendete Vorschläge. Import nur im selben Konto möglich; die Datei enthält den Entwurfstext.",
 "화면을 불러오고 그린 시간이에요. 100ms를 넘으면 느리게 느껴져요.": "Zeit zum Laden und Zeichnen der Ansichten. Über 100ms fühlt es sich langsam an.",
 "멈춰 있어요. 다시 켜면 다음 대화부터 저장해요.": "Pausiert. Schalte es wieder ein, dann wird ab dem nächsten Chat gespeichert.",
 "에이전트 대화를 저장하고 기억을 넣어요": "Speichert Agent-Chats und fügt Erinnerungen ein",
 "이 PC에 저장한 기억·세션·스킬 기록을 백업하고 되돌려요. 백업에는 모든 기억이 들어 있으니 안전한 곳에 두세요.": "Sichere und stelle die auf diesem PC gespeicherten Erinnerungen, Sitzungen und Skill-Einträge wieder her. Ein Backup enthält alle Erinnerungen, bewahre es daher sicher auf.",
 "뜻과 키워드로 함께 찾아요.": "Sucht nach Bedeutung und Schlüsselwörtern zugleich.",
 "CLAUDE.md·AGENTS.md·GEMINI.md의 규칙을 검토 대기로 가져와요": "Holt Regeln aus CLAUDE.md, AGENTS.md und GEMINI.md in die Prüfwarteschlange",
 "문서 › Arkism Backups · 하루 한 번 자동 (최근 7개)": "Dokumente › Arkism Backups · automatisch einmal täglich (die letzten 7)",
 "이 PC의 기억·세션·스킬 기록·설정을 모두 지워요. 백업 폴더와 에이전트 파일은 남아요. 되돌릴 수 없어요.": "Löscht alle Erinnerungen, Sitzungen, Skill-Einträge und Einstellungen auf diesem PC. Backup-Ordner und Agent-Dateien bleiben erhalten. Das lässt sich nicht rückgängig machen.",
