 "회의를 열 때 목록에서 고르는 이름이에요": "Der Name, den du beim Öffnen eines Meetings aus der Liste wählst",
 "주제는 회의를 열 때 따로 적어요. 여기에는 매번 같은 진행 순서·볼 기준·결과 모양을 적어요.": "Das Thema gibst du beim Öffnen des Meetings ein. Schreib hier auf, was immer gleich bleibt: Ablauf, Prüfkriterien und Form des Ergebnisses.",
 "회의가 시작되면 서기가 이 순서로 읽고 브리핑해요": "Wenn das Meeting startet, liest der Protokollführer das in dieser Reihenfolge und gibt allen ein Briefing",
 "이 템플릿만 바꿀 설정": "Einstellungen nur für diese Vorlage",
 "비워 두면 팀 설정대로 해요. 이 템플릿으로 연 회의에서만 바뀌어요.": "Leer lassen, dann gilt die Teameinstellung. Änderungen gelten nur für Meetings, die mit dieser Vorlage geöffnet werden.",
 "어떤 회의인지 말하면 이름·진행 방법을 채워 드려요": "Sag, worum es im Meeting geht – Name und Ablauf werden für dich ausgefüllt",
 "어떤 회의에 쓸 템플릿인가요? 무엇을 정하고, 결과를 어떤 모양으로 받고 싶은지 말해 주세요.": "Für welches Meeting ist die Vorlage? Sag, was entschieden werden soll und in welcher Form du das Ergebnis haben möchtest.",
