 "토큰을 줄일 칸, 순서 문제, 멈추는 조건을 짚어 줘요": "Zeigt Stellen zum Token-Sparen, Probleme in der Reihenfolge und Stopp-Bedingungen",
 "이 그래프를 읽고 고칠 곳을 4개까지 짚어 드려요. 특히 볼 곳이 있으면 말해 주세요. 실행할 때는 검토하지 않아요.": "Ich lese diesen Graphen und zeige dir bis zu 4 Stellen zum Verbessern. Sag mir, falls ich zuerst irgendwo genauer hinschauen soll. Beim Ausführen wird nicht geprüft.",
