 "이 버전으로 변경": "Zu dieser Version wechseln",
 "저장할 때마다 버전이 하나 생겨요. 다른 버전으로 바꿔도 지금 버전은 남아요.": "Bei jedem Speichern entsteht eine Version. Wenn du wechselst, bleibt die aktuelle Version erhalten.",
