 "새 카테고리 이름": "Name der neuen Kategorie",
 "새 창으로 열지 못했어요.": "Konnte nicht in einem neuen Fenster geöffnet werden.",
 "기억 버블 지도 · 화살표로 고르고 +/−로 확대·축소, 끌어서 옮기기": "Memory-Blasenkarte · mit Pfeilen auswählen, mit +/− zoomen, durch Ziehen verschieben",
 "AI로 채우기": "Mit KI ausfüllen",
 "더 고칠 곳이 없어요.": "Es gibt nichts mehr zu verbessern.",
 "AI가 쓰는 중이에요…": "Die KI schreibt…",
 "고칠 곳이나 언제 실행할지 평소 말로 적으면 바뀐 목표·일정·단계를 보여 줘요": "Schreib in normalen Worten, was geändert werden soll oder wann es laufen soll, und du siehst das neue Ziel, den Zeitplan und die Schritte",
 "무엇을 고칠까요? '평일 아침 9시마다'처럼 평소 말로 적으면 언제 실행을 일정이나 웹훅으로 바꿔요. 목표를 바꾸고, 단계를 넣거나 빼고, 순서와 조건도 바꿀 수 있어요.": "Was soll geändert werden? Schreib in normalen Worten, wann es laufen soll, z. B. „werktags um 9 Uhr morgens“, und daraus wird ein Zeitplan oder ein Webhook. Du kannst auch das Ziel ändern, Schritte hinzufügen oder entfernen und Reihenfolge und Bedingungen anpassen.",
 "예: 평일 아침마다 돌려 줘 · 실패하면 2번까지 다시 찾게": "z. B. Lass es werktags morgens laufen · bei Fehler bis zu 2-mal erneut versuchen",
 "평일 아침마다 실행": "Jeden Werktagmorgen ausführen",
 "일월화수목금토": "SMDMDFS",
 "반": "halb",
 "시": "Stunde",
 "평소 말로 적어요 · 예: 평일 아침 9시, 매주 월·목 오후 3시 반": "Schreib es ganz normal · z. B. werktags um 9 Uhr, jeden Mo und Do um 15:30 Uhr",
 "언제인지 알아듣지 못했어요. 요일과 시간을 넣어 다시 적어 주세요.": "Ich habe nicht verstanden, wann. Schreib die Wochentage und die Uhrzeit bitte noch einmal.",
 "한 번 묻기": "Einmal fragen",
 "단계마다 맡길 전문가를 고르고 할 일을 적어요. 위에서 아래로 차례대로 실행되고, 앞 단계 결과가 다음 단계로 넘어가요.": "Wähle für jeden Schritt, wer ihn übernimmt, und schreib auf, was zu tun ist. Die Schritte laufen von oben nach unten, und das Ergebnis jedes Schritts geht an den nächsten.",
 "자료 모으기": "Material sammeln",
 "핵심 정리": "Kernpunkte zusammenfassen",
 "검토하기": "Prüfen",
 "보고서 쓰기": "Bericht schreiben",
 "AI에게 한 번 묻기 (빠르고 싸요)": "Die KI einmal fragen (schnell und günstig)",
 "이 단계에서 할 일을 평소 말로 적어요 · 예: 받은 자료에서 핵심 3가지만 뽑아 표로 정리해 줘. 앞 단계 결과는 알아서 넘어와요": "Schreib ganz normal, was in diesem Schritt zu tun ist · z. B. Zieh die 3 wichtigsten Punkte aus dem Material und fass sie in einer Tabelle zusammen. Das Ergebnis des vorherigen Schritts kommt automatisch mit",
 "나에게 (기본)": "An mich (Standard)",
 "설정 › 메신저에서 먼저 연결해요": "Verbinde zuerst in Einstellungen › Messenger einen",
 "AI에게 한 번 묻기": "Die KI einmal fragen",
 "도구 없이 질문 한 번 · 빠르고 싸요": "Eine Frage ohne Tools · schnell und günstig",
 "이름을 적어 주세요.": "Gib bitte einen Namen ein.",
 "지시를 적어 주세요.": "Gib bitte die Anweisung ein.",
 "@이름을 적어 주세요.": "Gib bitte den @Namen ein.",
 "@이름은 띄어쓰기 없이 글자·숫자·_·-로 적어 주세요.": "Schreib den @Namen ohne Leerzeichen, nur mit Buchstaben, Zahlen, _ oder -.",
 "템플릿 이름을 적어 주세요.": "Gib bitte einen Vorlagennamen ein.",
 "서버의 SSH 키가 예전과 달라 접속을 막았어요. 관리자에게 새 지문을 확인한 뒤 다시 연결하세요.": "Der SSH-Schlüssel des Servers hat sich geändert, deshalb wurde die Verbindung blockiert. Lass den neuen Fingerabdruck vom Administrator bestätigen und verbinde dich dann erneut.",
 "서버 지문 확인을 취소했어요. 접속하지 않았습니다.": "Die Prüfung des Server-Fingerabdrucks wurde abgebrochen. Es wurde keine Verbindung hergestellt.",
 "서버 지문 확인이 필요해요. 다시 연결해 주세요.": "Der Server-Fingerabdruck muss geprüft werden. Verbinde dich bitte erneut.",
 "서버 지문을 가져오지 못했어요. 주소·포트와 SSH 연결을 확인하세요.": "Der Server-Fingerabdruck konnte nicht abgerufen werden. Prüfe Adresse, Port und SSH-Verbindung.",
 "지문 확인 시간이 지났어요. 다시 연결해 주세요.": "Die Zeit für die Prüfung des Fingerabdrucks ist abgelaufen. Verbinde dich bitte erneut.",
 "그사이 승인한 키가 바뀌었어요. 다시 연결해 주세요.": "Der bestätigte Schlüssel hat sich inzwischen geändert. Verbinde dich bitte erneut.",
 "저장한 서버 키를 확인할 수 없어 접속을 막았어요.": "Der gespeicherte Server-Schlüssel konnte nicht geprüft werden, deshalb wurde die Verbindung blockiert.",
 "서버의 SSH 지문을 확인하세요": "SSH-Fingerabdruck des Servers prüfen",
 "서버를 다시 설치했거나, 다른 서버에 연결되고 있을 수 있어요. 관리자에게 새 지문을 확인하기 전에는 접속하지 마세요.": "Der Server wurde möglicherweise neu installiert, oder du erreichst einen anderen Server. Verbinde dich erst, wenn der Administrator den neuen Fingerabdruck bestätigt hat.",
 "서버 관리자에게 다른 연락 수단으로 아래 지문을 확인해 주세요. 확인 전에는 개인 키·비밀번호로 로그인하지 않아요.": "Lass diesen Fingerabdruck über einen anderen Kanal vom Server-Administrator bestätigen. Vor der Bestätigung meldest du dich nicht mit privatem Schlüssel oder Passwort an.",
 "키 종류": "Schlüsseltyp",
 "새 지문": "Neuer Fingerabdruck",
 "이전 지문": "Vorheriger Fingerabdruck",
 "관리자에게 지문을 확인했고, 위 서버가 맞습니다.": "Ich habe den Fingerabdruck beim Administrator geprüft, und es ist der richtige Server.",
 "새 키로 교체하고 계속": "Schlüssel ersetzen und fortfahren",
 "이 키를 저장하고 계속": "Diesen Schlüssel speichern und fortfahren",
 "다음 목록에도 후보가 있어요.": "Auf der nächsten Seite gibt es weitere Kandidaten.",
