 "아직 @이름으로 부른 실행이 없어요.": "Noch keine mit @Name aufgerufenen Ausführungen.",
 "회의 결과": "Besprechungsergebnis",
 "하위 실행": "Untergeordnete Ausführung",
 "사람의 결정이 필요해요": "Eine Entscheidung durch einen Menschen ist nötig",
 "최신 실행을 다시 열어 주세요.": "Öffne bitte die aktuelle Ausführung erneut.",
 "중단을 요청했어요. 실제 종료 상태를 확인해 주세요.": "Stopp angefordert. Prüfe bitte den tatsächlichen Endstatus.",
 "결정을 보냈어요. 실행 상태를 다시 확인해요.": "Entscheidung gesendet. Der Ausführungsstatus wird erneut geprüft.",
 "보내지 못했어요. 상태가 바뀌었거나 권한이 없을 수 있어요. 다시 열어 확인해 주세요.": "Senden fehlgeschlagen. Der Status hat sich evtl. geändert oder dir fehlt die Berechtigung. Öffne es erneut und prüfe es.",
 "대화로 전달": "Zustellung per Unterhaltung",
 "보냈는지 확인되지 않아 자동으로 다시 보내지 않아요. 원래 대화와 저장된 메시지 영수증을 먼저 확인해 주세요.": "Es ist nicht bestätigt, ob gesendet wurde, daher wird nicht automatisch erneut gesendet. Prüfe zuerst die ursprüngliche Unterhaltung und die gespeicherten Nachrichtenbelege.",
 "권한이나 대화 상태를 확인해 주세요. 전달을 복구하려고 작업을 다시 실행하지 마세요.": "Prüfe die Berechtigungen und den Status der Unterhaltung. Führe die Aufgabe nicht erneut aus, um die Zustellung wiederherzustellen.",
 "아직 결론이 없어요.": "Es gibt noch kein Fazit.",
 "전체 회의 기록": "Gesamtes Besprechungsprotokoll",
 "전달 복구": "Zustellung wiederherstellen",
 "원래 대화 열기": "Ursprüngliche Unterhaltung öffnen",
 "전달 복구 방법": "Methode zur Wiederherstellung der Zustellung",
 "복구 방법 선택": "Wiederherstellungsmethode wählen",
 "미확인 부분부터 다시 보내기": "Ab dem unbestätigten Teil erneut senden",
 "이미 받은 메시지 확인하기": "Bereits empfangene Nachricht bestätigen",
 "다른 대화로 처음부터 보내기": "Von Anfang an an eine andere Unterhaltung senden",
 "원래 대화에서 미확인 부분이 전송되지 않았는지 확인해 주세요. 이미 받은 부분을 다시 보내면 중복될 수 있어요.": "Prüfe in der ursprünglichen Unterhaltung, ob der unbestätigte Teil nicht gesendet wurde. Wenn du einen bereits empfangenen Teil erneut sendest, kann er doppelt ankommen.",
 "원래 대화에서 현재 미확인 부분을 받은 메시지의 ID를 입력해요. 확인 후 다음 부분부터 이어서 전달해요.": "Gib die ID der Nachricht ein, die in der ursprünglichen Unterhaltung den aktuellen unbestätigten Teil enthält. Nach der Bestätigung wird ab dem nächsten Teil weiter zugestellt.",
 "입력한 새 대화에 전체 결과를 처음부터 보내요. 기존 대화와 메시지 영수증은 복구 이력에 남아요.": "Das gesamte Ergebnis wird von Anfang an an die eingegebene neue Unterhaltung gesendet. Die bisherige Unterhaltung und die Nachrichtenbelege bleiben im Wiederherstellungsverlauf.",
 "원래 대화를 확인했고 미확인 부분을 다시 보내는 데 동의해요.": "Ich habe die ursprüngliche Unterhaltung geprüft und stimme zu, den unbestätigten Teil erneut zu senden.",
 "입력한 메시지가 현재 미확인 부분의 실제 수신 메시지임을 확인했어요.": "Ich habe bestätigt, dass die eingegebene Nachricht den aktuellen unbestätigten Teil tatsächlich empfangen hat.",
 "새 목적지와 접근 권한을 확인했고 전체 결과를 보내는 데 동의해요.": "Ich habe das neue Ziel und die Zugriffsrechte geprüft und stimme zu, das gesamte Ergebnis zu senden.",
 "사람 계정의 복구 권한이 필요해요. 원래 대화를 확인한 뒤 방법을 선택해 주세요.": "Dafür ist die Wiederherstellungsberechtigung eines Personenkontos nötig. Prüfe die ursprüngliche Unterhaltung und wähle dann eine Methode.",
 "복구 내용 확인": "Wiederherstellungsdetails prüfen",
 "확인한 내용으로 복구 요청": "Wiederherstellung mit bestätigten Angaben anfordern",
 "확인한 Discord 메시지 ID": "Bestätigte Discord-Nachrichten-ID",
 "Arkism 봇 ID": "Arkism-Bot-ID",
 "Discord 서버 ID": "Discord-Server-ID",
 "Discord 채널 ID": "Discord-Kanal-ID",
 "Discord 대화·스레드 ID": "Discord-Unterhaltungs- oder Thread-ID",
 "복구 요청을 저장했어요. 실제 전달 상태를 다시 확인해 주세요.": "Wiederherstellung angefragt und gespeichert. Prüfe bitte noch einmal, ob wirklich zugestellt wurde.",
 "복구 요청 결과를 확인하지 못했어요. 새로고침해 현재 상태와 권한을 확인해 주세요.": "Das Ergebnis der Wiederherstellung konnte nicht bestätigt werden. Lade neu und prüfe den aktuellen Stand und die Berechtigungen.",
 "대화에서 ·": "Aus einer Unterhaltung ·",
 "AI 도움": "KI-Hilfe",
 "AI가 읽는 중…": "KI liest …",
 "글을 다 읽고 골라요": "Lies den ganzen Text, dann entscheide",
 "AI 도움을 누르면 승인할지 버릴지 이유와 함께 추천해요. 고르는 건 사람이에요.": "Mit KI-Hilfe bekommst du eine Empfehlung, ob du genehmigen oder verwerfen solltest, samt Begründung. Die Entscheidung triffst du.",
 "건넸는데 답에 안 쓰인 기억이에요": "Erinnerungen, die weitergegeben, aber in keiner Antwort genutzt wurden",
 "아직 맞으면 유지, 틀렸으면 고치기, 필요 없으면 잊기를 눌러 주세요.": "Wenn sie noch stimmt, tippe auf Behalten. Wenn sie falsch ist, auf Korrigieren. Wenn du sie nicht brauchst, auf Vergessen.",
 "골라야 바뀌어요": "Erst wenn du wählst, ändert sich etwas",
 "지운 기억도 이력에 남아요.": "Gelöschte Erinnerungen bleiben im Verlauf.",
 "원문은 7일 동안 보관돼요": "Originaltexte werden 7 Tage aufbewahrt",
 "기억이 답에 도움이 됐는지 봐요": "Sieh nach, ob Erinnerungen bei Antworten geholfen haben",
 "종류별 답에 쓰인 횟수": "Nutzung in Antworten nach Art",
 "종류별 넣은 횟수 (쓰인 기록은 아직 없어요)": "Weitergaben nach Art (noch keine Nutzung erfasst)",
 "에이전트가 세션에서 넣어 준 기억이에요. 한 줄이 세션 하나예요": "Erinnerungen, die Agenten in ihren Sitzungen bekommen haben. Eine Zeile ist eine Sitzung",
 "세션 정보 없음": "Keine Sitzungsinfos",
 "이전 기록": "Ältere Einträge",
 "이 제공자의 기록이 없어요.": "Keine Einträge von diesem Anbieter.",
 "프로젝트 밖": "Außerhalb eines Projekts",
 "저장소 없는 폴더": "Ordner ohne Repository",
 "zip으로 내보내기": "Als zip exportieren",
 "zip을 만들지 못했어요. 잠시 뒤 다시 시도해 주세요.": "Die zip konnte nicht erstellt werden. Versuche es gleich noch einmal.",
 "zip 파일": "zip-Datei",
 "zip이 160KB보다 커요. GitHub에 올려 주소로 설치해 주세요.": "Die zip ist größer als 160KB. Lade sie auf GitHub hoch und installiere sie über die Adresse.",
 "서버가 zip을 확인하고 있어요. 1분쯤 걸려요…": "Der Server prüft die zip. Das dauert etwa 1 Minute …",
 "마지막 분석": "Letzte Analyse",
 "복사했어요": "Kopiert",
 "복사하지 못했어요": "Kopieren fehlgeschlagen",
