 "본 대화": "Gesehene Unterhaltungen",
 "건너뜀·보류·실패": "Übersprungen · zurückgestellt · fehlgeschlagen",
 "이유": "Grund",
 "마지막으로 분석을 끝낸 때": "Zuletzt abgeschlossene Analyse",
 "그때 나온 후보": "Kandidaten damals",
 "서버가 아직 분석 결과를 보고하지 않았어요.": "Der Server hat noch kein Analyseergebnis gemeldet.",
 "명령 복사": "Befehl kopieren",
 "에이전트 설정 열기": "Agent-Einstellungen öffnen",
 "대화가 끝나고 5분 쉬면 분석해요": "Analysiert, wenn eine Unterhaltung 5 Minuten ruht",
 "대화 원문이 보관되기를 기다려요": "Warte darauf, dass der Originaltext der Unterhaltung archiviert wird",
 "비공개로 표시한 대화라 건너뛰었어요": "Übersprungen: Die Unterhaltung ist als privat markiert",
 "저장 정책 승인을 기다려요": "Warte auf die Genehmigung der Speicherrichtlinie",
 "같은 대화의 앞 묶음을 기다려요": "Warte auf den vorherigen Block derselben Unterhaltung",
 "모델 사용 한도에 걸려 1시간 뒤 다시 해요": "Das Modell-Nutzungslimit ist erreicht. Neuer Versuch in 1 Stunde",
 "서버가 분석 요청을 거부했어요 (로그인 만료)": "Der Server hat die Analyseanfrage abgelehnt (Anmeldung abgelaufen)",
 "서버가 분석 요청을 거부했어요 (권한 없음)": "Der Server hat die Analyseanfrage abgelehnt (keine Berechtigung)",
 "서버가 분석 요청을 거부했어요. 에이전트 로그인을 확인해 주세요.": "Der Server hat die Analyseanfrage abgelehnt. Prüfe die Anmeldung des Agenten.",
 "최근 2시간 동안 서버의 분석이 돌지 않았어요. 서버에서 분석 타이머를 켜 주세요.": "In den letzten 2 Stunden lief keine Analyse auf dem Server. Starte den Analyse-Timer auf dem Server.",
 "분석은 돌고 있지만 대화가 끝나지 않았거나 기다리는 중이에요.": "Die Analyse läuft, aber Unterhaltungen sind noch nicht beendet oder warten.",
 "취소했어요": "Abgebrochen",
 "서버에 닿지 못했어요. 연결을 확인하고 다시 시도해 주세요.": "Der Server ist nicht erreichbar. Prüfe die Verbindung und versuche es noch einmal.",
 "서버가 1분 넘게 답하지 않아요. 잠시 뒤 다시 시도해 주세요.": "Der Server antwortet seit über 1 Minute nicht. Versuche es gleich noch einmal.",
 "11분 안에 답이 오지 않았어요. 다시 시도해 주세요.": "Innerhalb von 11 Minuten kam keine Antwort. Versuche es noch einmal.",
 "AI가 읽는 중… 최대 11분 걸려요.": "KI liest … Das kann bis zu 11 Minuten dauern.",
 "AI가 읽는 중… 보통 1분 안에 끝나요.": "KI liest … Das dauert meist unter 1 Minute.",
 "AI 도움을 취소했어요. 후보는 그대로예요.": "KI-Hilfe abgebrochen. Der Kandidat bleibt unverändert.",
 "AI 제안을 취소했어요. 기억은 그대로예요.": "KI-Vorschlag abgebrochen. Die Erinnerung bleibt unverändert.",
 "서버가 아직 이 선택을 몰라요. 서버를 최신 판으로 올린 뒤 다시 해 주세요.": "Der Server kennt diese Auswahl noch nicht. Aktualisiere den Server und versuche es dann noch einmal.",
 "이대로 적용": "So übernehmen",
 "적용하면 이렇게 돼요. 아직 바뀌지 않았어요.": "So sieht es nach dem Übernehmen aus. Noch wurde nichts geändert.",
 "남길 기억은 계속 쓰고, 넘길 기억은 기억 이력에 남아요.": "Die Erinnerung, die bleibt, wird weiter genutzt. Die andere landet im Erinnerungsverlauf.",
 "두 기억을 다 그대로 써요. 같은 제안은 다시 하지 않아요.": "Beide Erinnerungen bleiben in Benutzung. Derselbe Vorschlag kommt nicht wieder.",
 "넘길 기억": "Wird abgelöst",
 "둘 다": "Beide",
 "둘 다 지웠어요. 기억 이력에 남아요.": "Beide gelöscht. Sie bleiben im Erinnerungsverlauf.",
 "두 기억을 다 지울까요?": "Beide Erinnerungen löschen?",
 "둘 다 더는 쓰이지 않아요. 기억 이력에는 남아요.": "Keine von beiden wird mehr genutzt. Beide bleiben im Erinnerungsverlauf.",
 "어느 쪽을 골라도 지우지 않아요. 넘긴 기억은 기억 이력에 남아요.": "Egal, was du wählst, es wird nichts gelöscht. Die zur Seite gelegte Erinnerung bleibt im Erinnerungsverlauf.",
 "지우지 못했어요.": "Löschen fehlgeschlagen.",
 "오래된 기억": "Veraltet",
 "이미 바뀜": "Schon geändert",
 "사용하지 않음": "Nicht genutzt",
 "사실과 다름": "Nicht wahr",
 "왜 지우나요?": "Warum löschen?",
 "무엇을 지울까요": "Was soll gelöscht werden?",
 "지우는 이유": "Grund fürs Löschen",
 "메모 (선택)": "Notiz (optional)",
 "이유를 하나 골라 주세요.": "Wähle bitte einen Grund aus.",
 "오래된 기억일 수 있어요": "Diese Erinnerung ist vielleicht veraltet",
 "왜 잊나요?": "Warum vergessen?",
 "고친 내용과 지금 기억을 왜 지우나요?": "Warum werden die Änderung und die aktuelle Erinnerung gelöscht?",
 "왜 버리나요?": "Warum verwerfen?",
 "버리지 못했어요.": "Verwerfen fehlgeschlagen.",
 "다시 볼게요·괜찮아요는 기억을 바꾸지 않아요. 지운 기억은 지운 이유와 함께 기억 이력에 남아요.": "Mit „Noch mal ansehen“ und „Passt so“ ändern sich Erinnerungen nicht. Eine gelöschte Erinnerung bleibt mit ihrem Grund im Erinnerungsverlauf.",
 "지우지 못했어요. 위 알림을 확인해 주세요.": "Löschen fehlgeschlagen. Sieh dir den Hinweis oben an.",
 "통과 기준은 평가 서버의 기본값으로 채워요. 바꾸려면 고급 설정을 여세요.": "Die Bestehenskriterien kommen aus den Standardwerten des Evaluierungsservers. Öffne die erweiterten Einstellungen, um sie zu ändern.",
 "다른 사람이 만든 통과 평가가 있어야 승인할 수 있어요.": "Zum Genehmigen braucht es eine bestandene Evaluierung von jemand anderem.",
 "저장 대기": "Wartet aufs Speichern",
 "중단": "Gestoppt",
 "비교 실행 중": "Vergleich läuft",
 "결과 저장 대기": "Ergebnis wartet aufs Speichern",
 "결과 저장됨": "Ergebnis gespeichert",
 "실행 중단": "Lauf gestoppt",
 "모델 실행은 끝났고, 서버에 저장하는 것만 남았어요.": "Der Modelllauf ist fertig. Es fehlt nur noch das Speichern auf dem Server.",
 "새 비교": "Neuer Vergleich",
 "평가 서버": "Evaluierungsserver",
 "설정·기록 보기": "Einstellungen und Verlauf ansehen",
 "실행 기록을 불러왔어요. 같은 과제로 다시 비교할 수 있어요.": "Der Laufverlauf wurde geladen. Du kannst mit denselben Aufgaben noch einmal vergleichen.",
 "아직 비교 기록이 없어요": "Noch keine Vergleiche",
 "다시 저장 시도": "Erneut speichern",
 "저장된 평가로 검토": "Mit gespeicherter Evaluierung prüfen",
 "기준": "Kriterien",
 "제한 없음": "Kein Limit",
 "평가 과제를 불러오면 평가 서버의 기본값으로 채워져요.": "Sobald die Evaluierungsaufgaben geladen sind, wird das mit den Standardwerten des Evaluierungsservers gefüllt.",
 "아직 검토하지 않은 교훈은 독립 관측이 3개 이상일 때만 써요.": "Noch nicht geprüfte Lektionen werden nur genutzt, wenn es mindestens 3 unabhängige Beobachtungen gibt.",
 "개선안을 저장했어요. ‘비교 평가’에서 기존 버전과 비교하세요.": "Verbesserungsvorschlag gespeichert. Vergleiche ihn unter „Vergleich“ mit der aktuellen Version.",
 "서버가 요청을 거절했어요. 현재 근거와 권한을 확인한 뒤 입력을 다시 고를 수 있어요.": "Der Server hat die Anfrage abgelehnt. Prüfe die aktuellen Belege und Berechtigungen, dann kannst du die Eingaben neu wählen.",
 "처리 결과를 확인할 생성 요청이 있어요. 오른쪽에서 결과를 다시 확인하세요.": "Bei einer Erstellungsanfrage muss das Ergebnis noch geprüft werden. Prüfe es rechts noch einmal.",
 "입력 다시 고르기": "Eingaben neu wählen",
 "서버가 요청을 거절한 뒤에 다시 고를 수 있어요.": "Du kannst neu wählen, nachdem der Server die Anfrage abgelehnt hat.",
 "비교 대상": "Verglichene Versionen",
 "기존 버전과 바뀐 줄이 없어요.": "Keine Zeile unterscheidet sich von der aktuellen Version.",
