 "카드마다 저장할지 버릴지 골라 한 번에 반영해요. 버리면 기억하지 않아요.": "Wähle bei jeder Karte „Speichern“ oder „Verwerfen“ und übernimm alles auf einmal. Verworfenes wird nicht gemerkt.",
