 "둘 다 기억으로 써요": "Beides wird als Erinnerung behalten",
 "어디서 왔는지 불러오지 못했어요. 다시 선택해 주세요.": "Die Herkunft konnte nicht geladen werden. Bitte wähle noch einmal.",
