 "위 문장은 저장할 때 남긴 발췌예요. 정확한 말은 대화에서 확인해 주세요.": "Der Satz oben ist ein Auszug, der beim Speichern festgehalten wurde. Den genauen Wortlaut findest du in der Unterhaltung.",
