 "새 후보는 버려요": "Der neue Kandidat wird verworfen",
 "쓰는 범위 · AI 추천이 기본, 정하는 건 사람이에요": "Gilt für · Die KI schlägt vor, entscheiden tust du",
 "어느 프로젝트인지 몰라 고를 수 없어요": "Das Projekt ist unbekannt, daher kannst du nichts auswählen",
 "넘길 내용을 찾지 못했어요. 서버를 최신 판으로 올리면 쓸 수 있어요.": "Es wurde nichts zum Übergeben gefunden. Aktualisiere den Server auf die neueste Version, dann klappt es.",
 "이어서 하기 명령": "Befehl zum Fortsetzen",
 "이 에이전트는 이어서 하기 명령을 몰라요.": "Dieser Agent kennt keinen Befehl zum Fortsetzen.",
 "다른 에이전트로 handoff": "An anderen Agenten übergeben (Handoff)",
 "이어서 하기": "Fortsetzen",
 "이어서 하기 명령을 복사했어요. 터미널에 붙여 넣으세요.": "Der Befehl zum Fortsetzen wurde kopiert. Füge ihn im Terminal ein.",
 "handoff ⌄": "Handoff ⌄",
 "잘 쓰이나 확인 보기": "Nutzungsprüfung ansehen",
 "내용이 낡았거나 너무 넓을 수 있어요. 고치거나 「잘 쓰이나 확인」에서 정리해 보세요.": "Der Inhalt ist vielleicht veraltet oder zu breit gefasst. Bearbeite ihn oder räume ihn in der „Nutzungsprüfung“ auf.",
