 "기록·사용량": "Verlauf & Nutzung",
 "실패가 많은 단계": "Schritte mit den meisten Fehlern",
 "실패한 단계가 없어요.": "Kein Schritt ist fehlgeschlagen.",
 "끝난 실행이 없어요": "Keine abgeschlossenen Läufe",
 "메뉴 접기": "Menü einklappen",
 "메뉴 펼치기": "Menü ausklappen",
 "현재 위치": "Aktueller Ort",
 "이 워크플로우 실행만 세요. 테스트 실행은 빼요.": "Zählt nur Läufe dieses Workflows, ohne Testläufe.",
 "사용량을 불러오지 못했어요.": "Die Nutzung konnte nicht geladen werden.",
 "다시 돌릴 실패 기록을 찾지 못했어요.": "Es wurde kein fehlgeschlagener Lauf zum Wiederholen gefunden.",
 "마지막 실패 실행을 실패한 곳부터 다시 돌릴까요? 끝난 단계는 결과를 그대로 써요.": "Den letzten fehlgeschlagenen Lauf ab der Fehlerstelle neu starten? Abgeschlossene Schritte behalten ihr Ergebnis.",
 "이름은 저장할 때 정해요": "Der Name wird beim Speichern festgelegt",
