 "돌려줄 것": "Rückgabe",
 "앞 노드 결과": "Ergebnis des vorherigen Knotens",
 "부르는 법": "So rufst du ihn auf",
 "여기부터 눌러 보세요": "Fang hier an",
 "AI 작업": "KI-Aufgabe",
 "비우면 앞 단계 결과로 일해요": "Leer lassen, dann arbeitet er mit dem Ergebnis des vorherigen Schritts",
 "고르지 않음": "Keine Auswahl",
 "고르면 그 전문가의 지시·모델을 채워요": "Wenn du einen auswählst, werden Anweisungen und Modell dieses Experten eingetragen",
 "이름, 실행 범위, 나눠서 맡기기, 스킬은 자세히에서 정해요.": "Name, Ausführungsbereich, Aufteilen und Skills legst du unter „Details“ fest.",
 "이 노드를 전문가로 저장": "Diesen Knoten als Experten speichern",
 "전문가 불러오기 ›": "Experten laden ›",
 "하고 싶은 일을 한 줄로 적으면 AI가 노드를 짜 줘요 · 예: 매일 아침 열린 PR을 모아 요약해서 보내 줘": "Beschreibe in einer Zeile, was du willst, und die KI legt die Knoten an · z. B. Fasse jeden Morgen die offenen PRs zusammen und schick sie mir",
 "AI에게 맡길 일": "Aufgabe für die KI",
 "짜는 중…": "Wird angelegt…",
