 "무엇을 할지 한 줄 적어 주세요.": "Bitte schreib in einer Zeile, was zu tun ist.",
 "AI 작업 · 전문가 불러옴": "KI-Aufgabe · Experte geladen",
 "전문가로 저장": "Als Experten speichern",
 "저장할 때 정해요": "Wird beim Speichern festgelegt",
 "「AI 작업」 노드에 무엇을 할지 한 줄 적어요.": "Schreib im Knoten „KI-Aufgabe“ in einer Zeile, was zu tun ist.",
 "처음이라면": "Zum Einstieg",
 "만들어 둔 전문가가 있으면 노드에서 「전문가 불러오기」로 골라요. 잘 되는 노드는 전문가로 저장해 다시 써요.": "Wenn du schon Experten hast, wähle am Knoten „Experten laden“. Speichere einen gut funktionierenden Knoten als Experten, um ihn wiederzuverwenden.",
 "노드를 더하려면 아래 「+ 노드 추가」나 출력 점을 끌어요. 회의도 노드 종류에서 골라요.": "Um Knoten hinzuzufügen, nutze unten „+ Knoten hinzufügen“ oder zieh an einem Ausgangspunkt. Auch eine Besprechung wählst du über die Knotenart.",
 "모델·추론·스킬은 이 노드 그대로 넣어요. 다른 워크플로우에서 「전문가 불러오기」로 쓰고 @이름으로 불러요.": "Modell, Schlussfolgern und Skills werden von diesem Knoten übernommen. Nutze ihn in anderen Workflows über „Experten laden“ und rufe ihn mit @Name auf.",
