 "아직 로그인 안 됨": "Noch nicht angemeldet",
 "다른 계정으로 로그인": "Mit einem anderen Konto anmelden",
 "구독 대신 API 키로 연결해요": "Statt mit einem Abo mit einem API-Schlüssel verbinden",
 "로그인한 계정이 없어요. 구독으로 쓰려면 계정을 추가하고, API로 쓰려면 아래 'API 키'에서 키를 넣어요.": "Kein angemeldetes Konto. Füge ein Konto hinzu, um ein Abo zu nutzen, oder gib unten unter „API-Schlüssel“ einen Schlüssel ein, um die API zu nutzen.",
 "로그인하거나 API 키를 넣으면 이 모델들을 쓸 수 있어요.": "Melde dich an oder gib einen API-Schlüssel ein, um diese Modelle zu nutzen.",
 "아직 받은 모델이 없어요. '목록 새로고침'으로 다시 받아 보세요.": "Noch keine Modelle geladen. Versuch „Liste aktualisieren“.",
 "이 PC의 Arkism이 아직 로그인 상태를 읽는 중이에요. 잠시 뒤 보여요.": "Arkism auf diesem PC liest noch den Anmeldestatus. Er erscheint gleich.",
 "잠시 뒤 다시 시험해 주세요.": "Teste in einem Moment noch einmal.",
