 "끄면 이 앱의 스킬 표에서만 숨겨요. 대화 수집은 그대로예요.": "Wenn du es ausschaltest, wird es nur in der Skill-Tabelle dieser App ausgeblendet. Chats werden weiterhin gesammelt.",
 "끄면 Arkism이 이 에이전트의 스킬과 대화를 더 읽지 않아요.": "Wenn du es ausschaltest, liest Arkism die Skills und Chats dieses Agenten nicht mehr.",
